VALIDATION_BASE_FUNCTION_METADATA = (('public.enforce_tutor_context_summary_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor context summaries are append-only';\nEND;\n"), ('public.enforce_tutor_planning_fact_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND current_setting('aearn.learning_track_purge_user_id', true) = OLD.user_id::text THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor planning intake facts are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_planning_question_event_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND current_setting('aearn.learning_track_purge_user_id', true) = OLD.user_id::text THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor planning question events are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_practice_shared_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION 'Practice shared authority rows are immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_practice_user_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Practice user facts are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_provider_attempt_receipt_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION 'Tutor provider attempt receipts are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_review_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Review receipts and items are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.tutor_plan_catalog_knowledge_key(uuid,uuid,uuid,text)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'sql', 'text', False, 'u', '\n  SELECT COALESCE(nodes.catalog_knowledge_key,nodes.knowledge_key)\n  FROM tutor_track_plan_nodes nodes\n  WHERE nodes.user_id=target_user AND nodes.track_id=target_track\n    AND nodes.revision_id=target_revision AND nodes.knowledge_key=target_knowledge;\n'), ('public.enforce_lesson_completion_run_597()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.completion_contract_version IS NOT NULL AND (NEW.state <> 'pending' OR NEW.lease_generation <> 0 OR NEW.attempt_count <> 0) THEN\n      RAISE EXCEPTION 'Completion Lesson runs must start pending and unconsumed' USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF NEW.completion_contract_version IS DISTINCT FROM OLD.completion_contract_version THEN\n    RAISE EXCEPTION 'Legacy Lesson rows cannot be converted or reopened' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.completion_contract_version IS NULL THEN RETURN NEW; END IF;\n  IF OLD.state IN ('completed', 'failed', 'cancelled') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal completion Lesson run is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF (to_jsonb(NEW) - ARRAY['state','attempt_count','lease_generation','lease_owner','lease_expires_at','failure_code','failure_message','source_set_hash','standard_document_id','personalized_document_id','assignment_id','updated_at','terminal_at'])\n       IS DISTINCT FROM\n     (to_jsonb(OLD) - ARRAY['state','attempt_count','lease_generation','lease_owner','lease_expires_at','failure_code','failure_message','source_set_hash','standard_document_id','personalized_document_id','assignment_id','updated_at','terminal_at'])\n     OR (OLD.source_set_hash IS NOT NULL AND NEW.source_set_hash IS DISTINCT FROM OLD.source_set_hash)\n     OR NEW.attempt_count < OLD.attempt_count\n     OR (OLD.state = 'running' AND NEW.state = 'claimed')\n     OR (OLD.state = 'claimed' AND NEW.state = 'pending') THEN\n    RAISE EXCEPTION 'Completion Lesson identity cannot be rewritten' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.lease_generation IS DISTINCT FROM OLD.lease_generation THEN\n    IF NEW.lease_generation <> OLD.lease_generation + 1\n       OR NOT ((OLD.state = 'pending' AND NEW.state = 'claimed')\n               OR (OLD.state = 'claimed' AND NEW.state = 'claimed' AND OLD.lease_expires_at <= clock_timestamp())\n               OR (OLD.state = 'running' AND NEW.state = 'running' AND OLD.lease_expires_at <= clock_timestamp()))\n       OR EXISTS (SELECT 1 FROM tutor_lesson_authoring_stage_attempts WHERE run_id = OLD.id AND state IN ('intent','outcome_unknown')) THEN\n      RAISE EXCEPTION 'Reclaim requires generation CAS and known step closure, never expiry alone' USING ERRCODE = '23514';\n    END IF;\n  ELSIF NEW.lease_owner IS DISTINCT FROM OLD.lease_owner AND NEW.state NOT IN ('completed','failed','cancelled') THEN\n    RAISE EXCEPTION 'Lesson owner change requires generation CAS' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.lease_generation = OLD.lease_generation AND NEW.lease_expires_at > OLD.lease_expires_at\n     AND OLD.lease_expires_at <= clock_timestamp() THEN\n    RAISE EXCEPTION 'Heartbeat cannot revive an expired Lesson lease' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at\n     AND NEW.lease_expires_at > clock_timestamp() + interval '120 seconds' THEN\n    RAISE EXCEPTION 'Lesson liveness lease is bounded to 120 seconds' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.state = 'failed' AND OLD.state <> 'failed' AND OLD.lease_expires_at <= clock_timestamp() THEN\n    RAISE EXCEPTION 'Expired Lesson owner cannot terminalize recoverable work' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.state = 'failed' AND OLD.state <> 'failed' AND EXISTS (\n    SELECT 1 FROM tutor_lesson_authoring_stage_attempts WHERE run_id = OLD.id AND state = 'result_saved'\n  ) THEN\n    RAISE EXCEPTION 'Committed Lesson results require reconciliation before failure' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.state = 'completed' AND OLD.state <> 'completed' THEN\n    IF OLD.lease_expires_at <= clock_timestamp()\n       OR EXISTS (SELECT 1 FROM tutor_lesson_authoring_stage_attempts WHERE run_id = OLD.id AND state IN ('intent','outcome_unknown','result_saved'))\n       OR NOT EXISTS (\n         SELECT 1 FROM tutor_lesson_authoring_stage_attempts personal\n         JOIN tutor_lesson_authoring_stage_attempts standard ON standard.id = personal.standard_attempt_id\n         JOIN tutor_lesson_documents pd ON pd.id = NEW.personalized_document_id AND pd.content_hash = personal.document_hash\n         JOIN tutor_lesson_documents sd ON sd.id = NEW.standard_document_id AND sd.content_hash = standard.document_hash\n         JOIN tutor_lesson_assignments assignment ON assignment.id = NEW.assignment_id AND assignment.document_id = pd.id\n         WHERE personal.state = 'accepted' AND standard.state = 'accepted'\n           AND personal.stage_kind = 'personalized' AND standard.stage_kind = 'standard'\n           AND (personal.user_id, personal.track_id, personal.knowledge_key) = (NEW.user_id, NEW.track_id, NEW.knowledge_key)\n           AND personal.dependency_json ->> 'profile_hash' = NEW.profile_hash\n           AND personal.dependency_json #>> '{evidence,legacy_source_set_hash}' = NEW.source_set_hash\n           AND (pd.user_id, pd.track_id, pd.knowledge_key, pd.profile_hash, pd.source_set_hash) =\n               (NEW.user_id, NEW.track_id, NEW.knowledge_key, NEW.profile_hash, NEW.source_set_hash)\n           AND (assignment.user_id, assignment.track_id, assignment.knowledge_key) =\n               (NEW.user_id, NEW.track_id, NEW.knowledge_key)\n           AND sd.source_set_hash = NEW.source_set_hash\n           AND pd.standard_document_id = sd.id\n       ) THEN\n      RAISE EXCEPTION 'Lesson publication requires complete accepted stages in original atomic publish' USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND "), ('public.enforce_lesson_evidence_units_597()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE unit jsonb; raw_bytes bytea;\nBEGIN\n  IF NEW.evidence_schema_version IS NULL THEN RETURN NEW; END IF;\n  IF NEW.evidence_schema_version <> 'lesson_evidence_units_v1'\n     OR jsonb_typeof(NEW.evidence_units_json) <> 'array'\n     OR jsonb_array_length(NEW.evidence_units_json) <> 1 THEN\n    RAISE EXCEPTION 'Invalid versioned Lesson evidence' USING ERRCODE = '23514';\n  END IF;\n  unit := NEW.evidence_units_json -> 0;\n  raw_bytes := convert_to(unit ->> 'text', 'UTF8');\n  IF jsonb_typeof(unit) <> 'object' OR unit - ARRAY['text','content_hash','start_byte','end_byte'] <> '{}'::jsonb\n     OR jsonb_typeof(unit -> 'text') IS DISTINCT FROM 'string'\n     OR jsonb_typeof(unit -> 'start_byte') IS DISTINCT FROM 'number'\n     OR jsonb_typeof(unit -> 'end_byte') IS DISTINCT FROM 'number'\n     OR (unit ->> 'start_byte')::integer IS DISTINCT FROM 0\n     OR octet_length(raw_bytes) NOT BETWEEN 1 AND 64000\n     OR (unit ->> 'end_byte')::integer IS DISTINCT FROM octet_length(raw_bytes)\n     OR (unit ->> 'content_hash') IS DISTINCT FROM NEW.chunk_content_hash\n     OR encode(digest(raw_bytes, 'sha256'), 'hex') IS DISTINCT FROM NEW.chunk_content_hash THEN\n    RAISE EXCEPTION 'Lesson evidence bytes/hash/scope mismatch' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND "), ('public.enforce_rag_d_binding_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'RAG D binding is immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_rag_d_selection_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF OLD.target_run_id IS NULL AND NEW.target_run_id IS NOT NULL\n       AND (NEW.handle, NEW.user_id, NEW.conversation_id, NEW.session_id, NEW.draft_id,\n            NEW.draft_version, NEW.content_hash, NEW.source_run_id, NEW.source_input_revision,\n            NEW.selection_digest, NEW.snapshot_json, NEW.idempotency_key, NEW.created_at)\n           IS NOT DISTINCT FROM\n           (OLD.handle, OLD.user_id, OLD.conversation_id, OLD.session_id, OLD.draft_id,\n            OLD.draft_version, OLD.content_hash, OLD.source_run_id, OLD.source_input_revision,\n            OLD.selection_digest, OLD.snapshot_json, OLD.idempotency_key, OLD.created_at)\n       THEN RETURN NEW;\n    END IF;\n  END IF;\n  RAISE EXCEPTION 'RAG D selection is immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_rag_d_semantic_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  IF TG_OP = 'UPDATE' AND OLD.review_status = 'dispatched' AND NEW.review_status = 'settled'\n     AND (NEW.id,NEW.user_id,NEW.conversation_id,NEW.run_id,NEW.input_revision,\n          NEW.decision_iteration,NEW.attempt_index,NEW.selection_handle,NEW.selection_digest,\n          NEW.parent_content_hash,NEW.candidate_digest,NEW.authority_hash,NEW.candidate_hash,\n          NEW.request_binding_hash,NEW.created_at)\n         IS NOT DISTINCT FROM\n         (OLD.id,OLD.user_id,OLD.conversation_id,OLD.run_id,OLD.input_revision,\n          OLD.decision_iteration,OLD.attempt_index,OLD.selection_handle,OLD.selection_digest,\n          OLD.parent_content_hash,OLD.candidate_digest,OLD.authority_hash,OLD.candidate_hash,\n          OLD.request_binding_hash,OLD.created_at)\n     THEN RETURN NEW;\n  END IF;\n  RAISE EXCEPTION 'RAG D semantic receipt is immutable after settlement' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_action_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_action_purge_allowed(OLD.invocation_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor action attempt, verification, and receipt rows are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_action_invocation_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_action_purge_allowed(OLD.id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor action invocations cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id\n     OR OLD.run_id IS DISTINCT FROM NEW.run_id\n     OR OLD.conversation_id IS DISTINCT FROM NEW.conversation_id\n     OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.input_revision IS DISTINCT FROM NEW.input_revision\n     OR OLD.lease_owner_id IS DISTINCT FROM NEW.lease_owner_id\n     OR OLD.lease_generation IS DISTINCT FROM NEW.lease_generation\n     OR OLD.action_generation IS DISTINCT FROM NEW.action_generation\n     OR OLD.idempotency_key IS DISTINCT FROM NEW.idempotency_key\n     OR OLD.stable_action_key IS DISTINCT FROM NEW.stable_action_key\n     OR OLD.action_id IS DISTINCT FROM NEW.action_id\n     OR OLD.action_version IS DISTINCT FROM NEW.action_version\n     OR OLD.descriptor_hash IS DISTINCT FROM NEW.descriptor_hash\n     OR OLD.owner_adapter_id IS DISTINCT FROM NEW.owner_adapter_id\n     OR OLD.task_kind IS DISTINCT FROM NEW.task_kind\n     OR OLD.origin IS DISTINCT FROM NEW.origin\n     OR OLD.catalog_digest IS DISTINCT FROM NEW.catalog_digest\n     OR OLD.policy_fingerprint IS DISTINCT FROM NEW.policy_fingerprint\n     OR OLD.selected_skill_reference IS DISTINCT FROM NEW.selected_skill_reference\n     OR OLD.request_hash IS DISTINCT FROM NEW.request_hash\n     OR OLD.resource_profile_hash IS DISTINCT FROM NEW.resource_profile_hash\n     OR OLD.resource_request_hash IS DISTINCT FROM NEW.resource_request_hash\n     OR OLD.parent_invocation_id IS DISTINCT FROM NEW.parent_invocation_id\n     OR OLD.retry_index IS DISTINCT FROM NEW.retry_index\n     OR OLD.requested_at IS DISTINCT FROM NEW.requested_at\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Tutor action invocation identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status IN ('verified', 'retryable_failed', 'permanent_failed', 'denied', 'cancelled', 'timed_out', 'superseded') THEN\n    RAISE EXCEPTION 'Terminal Tutor action invocation is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'requested' AND NEW.status IN ('admitted', 'denied') THEN RETURN NEW; END IF;\n  IF OLD.status = 'admitted' AND NEW.status IN ('running', 'cancel_requested', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.status = 'running' AND NEW.status IN (\n    'succeeded_unverified', 'retryable_failed', 'permanent_failed', 'denied',\n    'timed_out', 'cancel_requested', 'superseded'\n  ) THEN RETURN NEW; END IF;\n  IF OLD.status = 'cancel_requested' AND NEW.status IN ('cancelled', 'succeeded_unverified') THEN RETURN NEW; END IF;\n  IF OLD.status = 'succeeded_unverified' AND NEW.status IN (\n    'verified', 'retryable_failed', 'permanent_failed', 'cancel_requested', 'superseded'\n  ) THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Tutor action invocation lifecycle transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_activity_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor activity records are append-only';\nEND;\n"), ('public.enforce_tutor_artifact_supersession_receipt()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE successor uuid;\nBEGIN\n  IF NEW.state<>'superseded' OR OLD.state NOT IN ('pending','ready','active')\n     OR NOT EXISTS (SELECT 1 FROM tutor_teaching_sessions s\n                    WHERE s.id=NEW.teaching_session_id AND s.status='blocked') THEN\n    RETURN NULL;\n  END IF;\n  successor := tutor_artifact_supersession_successor(NEW.id);\n  IF successor IS NULL OR NOT EXISTS (\n    SELECT 1 FROM tutor_learning_artifact_events e\n    WHERE e.artifact_id=NEW.id AND e.user_id=NEW.user_id\n      AND e.conversation_id=NEW.conversation_id AND e.event_kind='terminal'\n      AND e.from_version=OLD.version AND e.to_version=NEW.version AND e.state='superseded'\n      AND e.event_key='teaching-supersession:' || successor::text || ':' || NEW.id::text\n      AND e.safe_payload_json->'owner_result'->>'reason_code'='teaching_authority_superseded'\n      AND e.safe_payload_json->'owner_result'->>'predecessor_session_id'=NEW.teaching_session_id::text\n      AND e.safe_payload_json->'owner_result'->>'successor_session_id'=successor::text\n  ) THEN\n    RAISE EXCEPTION 'Learning Artifact authority supersession requires its exact terminal receipt'\n      USING ERRCODE='23514';\n  END IF;\n  RETURN NULL;\nEND;\n"), ('public.enforce_tutor_branch_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor conversation branch evidence is append-only'\n    USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_branch_authority_insert()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  branch_row tutor_conversation_branches%ROWTYPE;\nBEGIN\n  IF TG_TABLE_NAME = 'tutor_conversation_branches' THEN\n    IF NEW.state <> 'active' THEN\n      RAISE EXCEPTION 'Tutor branch must open active' USING ERRCODE = '23514';\n    END IF;\n  ELSIF NEW.event_kind = 'authority_superseded' THEN\n    SELECT * INTO branch_row FROM tutor_conversation_branches\n      WHERE id = NEW.branch_id AND user_id = NEW.user_id\n        AND conversation_id = NEW.conversation_id AND artifact_id = NEW.artifact_id;\n    IF branch_row.id IS NULL OR branch_row.state <> 'active'\n       OR NEW.predecessor_event_id IS DISTINCT FROM branch_row.current_event_id\n       OR NEW.branch_version <> branch_row.version + 1\n       OR NOT tutor_branch_authority_replacement_valid(\n         branch_row.user_id, branch_row.conversation_id, branch_row.learning_track_id,\n         branch_row.knowledge_key, branch_row.teaching_session_id, NEW.superseding_session_id\n       ) THEN\n      RAISE EXCEPTION 'Tutor branch authority event requires an exact replacement'\n        USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_branch_item_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  scope_row tutor_run_branch_scopes%ROWTYPE;\nBEGIN\n  SELECT * INTO scope_row\n  FROM tutor_run_branch_scopes\n  WHERE run_id = NEW.run_id\n    AND branch_id = NEW.branch_id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND artifact_id = NEW.artifact_id;\n  IF scope_row.run_id IS NULL OR scope_row.branch_round <> NEW.branch_round THEN\n    RAISE EXCEPTION 'Tutor branch item run scope is mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NEW.item_kind = 'process' THEN\n    IF NEW.item_id <> NEW.run_id OR NOT EXISTS (\n      SELECT 1 FROM tutor_run_public_processes\n      WHERE run_id = NEW.run_id AND user_id = NEW.user_id\n        AND conversation_id = NEW.conversation_id\n    ) THEN\n      RAISE EXCEPTION 'Tutor branch process item is mismatched'\n        USING ERRCODE = '23514';\n    END IF;\n  ELSIF NEW.item_role = 'learner' THEN\n    IF NEW.item_id <> scope_row.source_message_id OR NOT EXISTS (\n      SELECT 1 FROM tutor_run_input_events\n      WHERE run_id = NEW.run_id AND message_id = NEW.item_id\n        AND input_revision = scope_row.source_input_revision\n    ) THEN\n      RAISE EXCEPTION 'Tutor branch learner message item is mismatched'\n        USING ERRCODE = '23514';\n    END IF;\n  ELSIF NOT EXISTS (\n    SELECT 1\n    FROM tutor_run_public_processes AS processes\n    JOIN tutor_messages AS messages\n      ON messages.id = processes.tutor_message_id\n     AND messages.conversation_id = processes.conversation_id\n    WHERE processes.run_id = NEW.run_id\n      AND processes.user_id = NEW.user_id\n      AND processes.conversation_id = NEW.conversation_id\n      AND messages.id = NEW.item_id\n      AND messages.role = 'tutor'\n  ) THEN\n    RAISE EXCEPTION 'Tutor branch Tutor message item is mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_branch_root_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  event_row tutor_conversation_branch_events%ROWTYPE;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor conversation branch cannot be deleted outside an authorized purge'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id\n     OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.conversation_id IS DISTINCT FROM NEW.conversation_id\n     OR OLD.learning_track_id IS DISTINCT FROM NEW.learning_track_id\n     OR OLD.knowledge_key IS DISTINCT FROM NEW.knowledge_key\n     OR OLD.teaching_session_id IS DISTINCT FROM NEW.teaching_session_id\n     OR OLD.checkpoint_id IS DISTINCT FROM NEW.checkpoint_id\n     OR OLD.artifact_id IS DISTINCT FROM NEW.artifact_id\n     OR OLD.predecessor_branch_id IS DISTINCT FROM NEW.predecessor_branch_id\n     OR OLD.depth IS DISTINCT FROM NEW.depth\n     OR OLD.opened_turn_id IS DISTINCT FROM NEW.opened_turn_id\n     OR OLD.opened_message_id IS DISTINCT FROM NEW.opened_message_id\n     OR OLD.opened_input_revision IS DISTINCT FROM NEW.opened_input_revision\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Tutor conversation branch identity is immutable'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('resolved', 'superseded') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal Tutor conversation branch is immutable'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NEW.version <> OLD.version + 1 OR NEW.current_event_id = OLD.current_event_id THEN\n    RAISE EXCEPTION 'Tutor conversation branch CAS must advance exactly once'\n      USING ERRCODE = '23514';\n  END IF;\n  SELECT * INTO event_row\n  FROM tutor_conversation_branch_events\n  WHERE id = NEW.current_event_id\n    AND branch_id = NEW.id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND artifact_id = NEW.artifact_id\n    AND predecessor_event_id = OLD.current_event_id\n    AND branch_version = NEW.version;\n  IF event_row.id IS NULL THEN\n    RAISE EXCEPTION 'Tutor conversation branch event lineage is missing'\n      USING ERRCODE = '23514';\n  END IF;\n  IF event_row.event_kind = 'turn_bound' THEN\n    IF NEW.state <> OLD.state OR NEW.round_count <> OLD.round_count + 1\n       OR NEW.latest_disposition IS DISTINCT FROM OLD.latest_disposition THEN\n      RAISE EXCEPTION 'Tutor conversation branch turn binding is inconsistent'\n        USING ERRCODE = '23514';\n    END IF;\n  ELSIF event_row.event_kind = 'response_recorded' THEN\n    IF NEW.state NOT IN ('active', 'resolved')\n       OR NEW.latest_disposition IS DISTINCT FROM event_row.disposition\n       OR NEW.round_count <> OLD.round_count THEN\n      RAISE EXCEPTION 'Tutor conversation branch response projection is inconsistent'\n        USING ERRCODE = '23514';\n    END IF;\n    IF NEW.state = 'resolved' AND (\n      NEW.resolved_turn_id IS DISTINCT FROM event_row.source_turn_id\n      OR NEW.resolved_at IS DISTINCT FROM event_row.created_at\n    ) THEN\n      RAISE EXCEPTION 'Tutor conversation branch resolution is inconsistent'\n        USING ERRCODE = '23514';\n    END IF;\n  ELSIF event_row.event_kind = 'authority_superseded' THEN\n    IF NEW.state <> 'superseded' OR NEW.round_count <> OLD.round_count\n       OR NEW.latest_disposition IS DISTINCT FROM OLD.latest_disposition\n       OR NEW.superseded_at IS DISTINCT FROM event_row.created_at\n       OR NEW.superseded_by_session_id IS DISTINCT FROM event_row.superseding_session_id\n       OR NOT tutor_branch_authority_replacement_valid(\n         OLD.user_id, OLD.conversation_id, OLD.learning_track_id, OLD.knowledge_key,\n         OLD.teaching_session_id, NEW.superseded_by_session_id\n       ) THEN\n      RAISE EXCEPTION 'Tutor conversation branch authority replacement is invalid'\n        USING ERRCODE = '23514';\n    END IF;\n  ELSE\n    RAISE EXCEPTION 'Tutor conversation branch update event kind is invalid'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_continuation_intent_insert_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  artifact_row tutor_learning_artifacts%ROWTYPE;\n  session_row tutor_teaching_sessions%ROWTYPE;\nBEGIN\n  SELECT * INTO artifact_row\n  FROM tutor_learning_artifacts\n  WHERE id = NEW.artifact_id AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND teaching_session_id = NEW.teaching_session_id\n    AND checkpoint_id = NEW.checkpoint_id\n    AND learning_track_id = NEW.learning_track_id\n    AND knowledge_key = NEW.knowledge_key;\n  SELECT * INTO session_row\n  FROM tutor_teaching_sessions\n  WHERE id = NEW.teaching_session_id AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id;\n  IF artifact_row.id IS NULL OR session_row.id IS NULL\n     OR artifact_row.version <> NEW.artifact_version\n     OR session_row.status NOT IN ('active', 'paused')\n     OR session_row.version <> NEW.session_version\n     OR NOT tutor_teaching_checkpoint_descends_from(\n       session_row.current_checkpoint_id, NEW.checkpoint_id,\n       NEW.teaching_session_id, NEW.user_id, NEW.conversation_id\n     )\n     OR (\n       NEW.source_kind IN ('static_display_timer', 'background_continuation')\n       AND session_row.mode <> 'guided'\n     )\n     OR session_row.track_version <> NEW.track_version\n     OR session_row.progress_version <> NEW.progress_version\n     OR session_row.assignment_version <> NEW.assignment_version THEN\n    RAISE EXCEPTION 'Tutor continuation intent authority is stale or mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_continuation_intent_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  event_row tutor_continuation_intent_events%ROWTYPE;\n  artifact_row tutor_learning_artifacts%ROWTYPE;\n  session_row tutor_teaching_sessions%ROWTYPE;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor continuation intent cannot be deleted outside an authorized purge'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id\n     OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.conversation_id IS DISTINCT FROM NEW.conversation_id\n     OR OLD.learning_track_id IS DISTINCT FROM NEW.learning_track_id\n     OR OLD.knowledge_key IS DISTINCT FROM NEW.knowledge_key\n     OR OLD.teaching_session_id IS DISTINCT FROM NEW.teaching_session_id\n     OR OLD.checkpoint_id IS DISTINCT FROM NEW.checkpoint_id\n     OR OLD.artifact_id IS DISTINCT FROM NEW.artifact_id\n     OR OLD.branch_id IS DISTINCT FROM NEW.branch_id\n     OR OLD.source_kind IS DISTINCT FROM NEW.source_kind\n     OR OLD.source_id IS DISTINCT FROM NEW.source_id\n     OR OLD.source_version IS DISTINCT FROM NEW.source_version\n     OR OLD.priority IS DISTINCT FROM NEW.priority\n     OR OLD.session_version IS DISTINCT FROM NEW.session_version\n     OR OLD.artifact_version IS DISTINCT FROM NEW.artifact_version\n     OR OLD.track_version IS DISTINCT FROM NEW.track_version\n     OR OLD.progress_version IS DISTINCT FROM NEW.progress_version\n     OR OLD.assignment_version IS DISTINCT FROM NEW.assignment_version\n     OR OLD.idempotency_key IS DISTINCT FROM NEW.idempotency_key\n     OR OLD.request_hash IS DISTINCT FROM NEW.request_hash\n     OR OLD.not_before IS DISTINCT FROM NEW.not_before\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Tutor continuation intent identity is immutable'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('consumed', 'cancelled', 'superseded') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal Tutor continuation intent is immutable'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NEW.version <> OLD.version + 1 OR NEW.current_event_id = OLD.current_event_id THEN\n    RAISE EXCEPTION 'Tutor continuation intent CAS must advance exactly once'\n      USING ERRCODE = '23514';\n  END IF;\n  SELECT * INTO event_row\n  FROM tutor_continuation_intent_events\n  WHERE id = NEW.current_event_id\n    AND intent_id = NEW.id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND artifact_id = NEW.artifact_id\n    AND predecessor_event_id = OLD.current_event_id\n    AND intent_version = NEW.version\n    AND state = NEW.state;\n  IF event_row.id IS NULL THEN\n    RAISE EXCEPTION 'Tutor continuation intent event lineage is missing'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NOT (\n    (OLD.state = 'pending' AND NEW.state IN ('claimed', 'consumed', 'cancelled', 'superseded'))\n    OR (OLD.state = 'claimed' AND NEW.state IN ('pending', 'consumed', 'cancelled', 'superseded'))\n  ) THEN\n    RAISE EXCEPTION 'Tutor continuation intent lifecycle transition is invalid'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'pending' AND NEW.state = 'consumed'\n     AND NEW.source_kind <> 'learner_message' THEN\n    RAISE EXCEPTION 'Only learner-message continuation may be consumed without a claim'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NEW.state = 'claimed' THEN\n    SELECT * INTO artifact_row\n    FROM tutor_learning_artifacts\n    WHERE id = NEW.artifact_id AND user_id = NEW.user_id\n      AND conversation_id = NEW.conversation_id\n      AND teaching_session_id = NEW.teaching_session_id\n      AND checkpoint_id = NEW.checkpoint_id\n      AND learning_track_id = NEW.learning_track_id\n      AND knowledge_key = NEW.knowledge_key;\n    SELECT * INTO session_row\n    FROM tutor_teaching_sessions\n    WHERE id = NEW.teaching_session_id AND user_id = NEW.user_id\n      AND conversation_id = NEW.conversation_id;\n    IF artifact_row.id IS NULL OR session_row.id IS NULL\n       OR artifact_row.version <> NEW.artifact_version\n       OR (\n         artifact_row.state IN ('completed', 'failed', 'cancelled', 'superseded')\n         AND (\n           NEW.source_kind IN ('learner_message', 'background_continuation')\n           OR (\n             NEW.source_kind IN ('expected_interactive_event', 'static_display_timer')\n             AND NOT tutor_demo_completion_continuation_valid(\n               NEW.artifact_id, NEW.user_id, NEW.conversation_id,\n               NEW.source_kind, NEW.source_id, NEW.source_version,\n               NEW.artifact_version\n             )\n           )\n         )\n       )\n       OR session_row.status NOT IN ('active', 'paused')\n       OR session_row.version < NEW.session_version\n       OR (\n         NEW.source_kind = 'learner_message'\n         AND (\n           session_row.version <> NEW.session_version\n           OR session_row.current_checkpoint_id <> NEW.checkpoint_id\n         )\n       )\n       OR (\n         NEW.source_kind <> 'learner_message'\n         AND NOT tutor_teaching_checkpoint_descends_from(\n           session_row.current_checkpoint_id, NEW.checkpoint_id,\n           NEW.teaching_session_id, NEW.user_id, NEW.conversation_id\n         )\n       )\n       OR (\n         NEW.source_kind IN ('static_display_timer', 'background_continuation')\n         AND session_row.mode <> 'guided'\n       )\n       OR session_row.track_version <> NEW.track_version\n       OR session_row.progress_version <> NEW.progress_version\n       OR session_row.assignment_version <> NEW.assignment_version THEN\n      RAISE EXCEPTION 'Tutor continuation intent authority is stale'\n        USING ERRCODE = '23514';\n    END IF;\n    IF EXISTS (\n      SELECT 1 FROM tutor_queued_inputs\n      WHERE user_id = NEW.user_id AND conversation_id = NEW.conversation_id\n        AND state = 'pending'\n    ) THEN\n      RAISE EXCEPTION 'Pending learner input preempts Tutor continuation intent'\n        USING ERRCODE = '23514';\n    END IF;\n    IF EXISTS (\n      SELECT 1 FROM tutor_conversation_branches\n      WHERE user_id = NEW.user_id AND conversation_id = NEW.conversation_id\n        AND state = 'active'\n    ) THEN\n      RAISE EXCEPTION 'Active Tutor branch must resolve before mainline continuation'\n        USING ERRCODE = '23514';\n    END IF;\n    IF EXISTS (\n      SELECT 1 FROM tutor_runs\n      WHERE user_id = NEW.user_id AND conversation_id = NEW.conversation_id\n        AND origin = 'interactive' AND terminal_outcome IS NULL\n        AND cancelled_at IS NULL AND superseded_by_run_id IS NULL\n    ) THEN\n      RAISE EXCEPTION 'Tutor conversation already has a publishable foreground Turn'\n        USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  IF NEW.state = 'consumed' THEN\n    IF NOT EXISTS (\n      SELECT 1\n      FROM tutor_run_teaching_scopes\n      WHERE run_id = NEW.consumed_run_id\n        AND user_id = NEW.user_id\n        AND conversation_id = NEW.conversation_id\n        AND teaching_session_id = NEW.teaching_session_id\n        AND track_id = NEW.learning_track_id\n        AND knowledge_key = NEW.knowledge_key\n        AND (\n          (\n            NEW.source_kind = 'learner_message'\n            AND checkpoint_id = NEW.checkpoint_id\n            AND session_version = NEW.session_version\n          )\n          OR\n          (\n            NEW.source_kind <> 'learner_message'\n            AND session_version >= NEW.session_version\n            AND tutor_teaching_checkpoint_descends_from(\n              checkpoint_id, NEW.checkpoint_id, NEW.teaching_session_id,\n              NEW.user_id, NEW.conversation_id\n            )\n          )\n        )\n    ) THEN\n      RAISE EXCEPTION 'Tutor continuation consumed Turn scope is mismatched'\n        USING ERRCODE = '23514';\n    END IF;\n    IF NEW.branch_id IS NOT NULL AND NOT EXISTS (\n      SELECT 1 FROM tutor_run_branch_scopes\n      WHERE run_id = NEW.consumed_run_id AND branch_id = NEW.branch_id\n        AND user_id = NEW.user_id AND conversation_id = NEW.conversation_id\n        AND artifact_id = NEW.artifact_id\n    ) THEN\n      RAISE EXCEPTION 'Tutor branch continuation consumed Turn is not branch-scoped'\n        USING ERRCODE = '23514';\n    END IF;\n    IF NEW.branch_id IS NULL AND EXISTS (\n      SELECT 1 FROM tutor_run_branch_scopes\n      WHERE run_id = NEW.consumed_run_id\n    ) THEN\n      RAISE EXCEPTION 'Tutor mainline continuation Turn cannot remain in a branch'\n        USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_conversation_event_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND current_setting('aearn.learning_track_purge_user_id', true) = OLD.user_id::text THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor conversation events are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_conversation_runtime_thread_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor conversation runtime threads are retained private state' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id\n     OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n     OR NEW.runtime_kind IS DISTINCT FROM OLD.runtime_kind\n     OR NEW.runtime_version IS DISTINCT FROM OLD.runtime_version\n     OR NEW.protocol_version IS DISTINCT FROM OLD.protocol_version\n     OR NEW.model IS DISTINCT FROM OLD.model\n     OR NEW.model_provider IS DISTINCT FROM OLD.model_provider\n     OR NEW.external_thread_id IS DISTINCT FROM OLD.external_thread_id\n     OR NEW.migration_mode IS DISTINCT FROM OLD.migration_mode THEN\n    RAISE EXCEPTION 'Tutor conversation runtime thread identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'retired' AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Retired Tutor conversation runtime thread is immutable' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_demo_completion_receipt()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  artifact_row tutor_learning_artifacts%ROWTYPE;\n  session_row tutor_teaching_sessions%ROWTYPE;\nBEGIN\n  IF TG_OP <> 'INSERT' THEN\n    IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RETURN OLD;\n    END IF;\n    RAISE EXCEPTION 'Tutor demonstration completion receipt is append-only'\n      USING ERRCODE = '23514';\n  END IF;\n\n  SELECT * INTO artifact_row\n  FROM tutor_learning_artifacts\n  WHERE id = NEW.artifact_id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND learning_track_id = NEW.learning_track_id\n    AND teaching_session_id = NEW.teaching_session_id\n    AND checkpoint_id = NEW.checkpoint_id;\n  SELECT * INTO session_row\n  FROM tutor_teaching_sessions\n  WHERE id = NEW.teaching_session_id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND track_id = NEW.learning_track_id;\n\n  IF artifact_row.id IS NULL OR session_row.id IS NULL\n     OR artifact_row.artifact_kind <> 'demonstration'\n     OR artifact_row.presentation_kind <> 'demonstration_v2'\n     OR artifact_row.state NOT IN ('ready', 'active')\n     OR artifact_row.version <> NEW.artifact_version\n     OR artifact_row.presentation_hash <> NEW.descriptor_hash\n     OR session_row.status NOT IN ('active', 'paused')\n     OR session_row.current_checkpoint_id <> NEW.checkpoint_id THEN\n    RAISE EXCEPTION 'Tutor demonstration completion authority is stale or mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_execution_job_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    IF OLD.launch_token IS NOT NULL\n       AND (\n         NEW.launch_token IS DISTINCT FROM OLD.launch_token\n         OR NEW.launch_generation IS DISTINCT FROM OLD.launch_generation\n         OR NEW.launch_reserved_at IS DISTINCT FROM OLD.launch_reserved_at\n       )\n    THEN\n      RAISE EXCEPTION USING\n        ERRCODE = '23514',\n        MESSAGE = 'execution launch reservation is immutable';\n    END IF;\n\n    IF OLD.launch_token IS NULL\n       AND NEW.launch_token IS NOT NULL\n       AND NOT (OLD.state = 'claimed' AND NEW.state = 'launch_reserved')\n    THEN\n      RAISE EXCEPTION USING\n        ERRCODE = '23514',\n        MESSAGE = 'execution launch token may only be allocated during reservation';\n    END IF;\n\n    IF OLD.state IN ('completed', 'timed_out', 'cancelled', 'unavailable', 'launch_uncertain', 'failed') THEN\n      IF NEW.state NOT IN ('completed', 'timed_out', 'cancelled', 'unavailable', 'launch_uncertain', 'failed') THEN\n        RAISE EXCEPTION USING\n          ERRCODE = '23514',\n          MESSAGE = 'execution terminal state cannot become non-terminal';\n      END IF;\n\n      IF NEW.state <> OLD.state AND NEW.state <> 'failed' THEN\n        RAISE EXCEPTION USING\n          ERRCODE = '23514',\n          MESSAGE = 'execution terminal state may only converge to failed during cleanup';\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_inbox_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    IF OLD.user_id IS DISTINCT FROM NEW.user_id\n       OR OLD.activity_id IS DISTINCT FROM NEW.activity_id\n       OR OLD.message IS DISTINCT FROM NEW.message\n       OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor inbox identity is immutable';\n    END IF;\n    IF OLD.state <> 'unread' OR NEW.state NOT IN ('read', 'dismissed') THEN\n      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor inbox lifecycle transition is invalid';\n    END IF;\n  ELSIF TG_OP = 'DELETE' THEN\n    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor inbox items are not deleted physically';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_knowledge_check_receipt_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP='DELETE' AND current_setting('aearn.learning_track_purge_user_id',true)=OLD.user_id::text THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Knowledge check receipts are append-only' USING ERRCODE='23514';\nEND;\n"), ('public.enforce_tutor_knowledge_check_receipt_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM tutor_learning_artifacts AS artifacts\n    WHERE artifacts.id=NEW.artifact_id\n      AND artifacts.user_id=NEW.user_id\n      AND artifacts.conversation_id=NEW.conversation_id\n      AND artifacts.learning_track_id=NEW.learning_track_id\n      AND artifacts.knowledge_key=NEW.knowledge_key\n      AND artifacts.teaching_session_id=NEW.teaching_session_id\n      AND artifacts.checkpoint_id=NEW.checkpoint_id\n      AND artifacts.version=NEW.artifact_version\n      AND artifacts.owner_kind='learning_item'\n      AND artifacts.artifact_kind='knowledge_check'\n      AND artifacts.state IN ('active','ready')\n  ) THEN\n    RAISE EXCEPTION 'Knowledge check receipt scope is stale or mismatched' USING ERRCODE='23514';\n  END IF;\n  IF TG_TABLE_NAME='tutor_knowledge_check_response_receipts' THEN\n    IF NEW.learning_item_version_id<>(\n      SELECT owner_id FROM tutor_learning_artifacts WHERE id=NEW.artifact_id\n    ) THEN\n      RAISE EXCEPTION 'Knowledge check response owner is stale or mismatched' USING ERRCODE='23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_learning_artifact_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Learning Artifact evidence rows are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_learning_artifact_attempt_link_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  artifact_row tutor_learning_artifacts%ROWTYPE;\nBEGIN\n  SELECT * INTO artifact_row\n  FROM tutor_learning_artifacts\n  WHERE id = NEW.artifact_id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND teaching_session_id = NEW.teaching_session_id\n    AND learning_track_id = NEW.learning_track_id;\n  IF artifact_row.id IS NULL\n     OR NEW.artifact_version <> artifact_row.version\n     OR NOT tutor_learning_artifact_attempt_owner_matches(\n       artifact_row.user_id,\n       artifact_row.conversation_id,\n       artifact_row.learning_track_id,\n       artifact_row.knowledge_key,\n       artifact_row.teaching_session_id,\n       artifact_row.owner_kind,\n       artifact_row.owner_id,\n       NEW.attempt_id\n     ) THEN\n    RAISE EXCEPTION 'Learning Artifact Attempt link scope is mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_learning_artifact_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Learning Artifact cannot be deleted outside an authorized purge'\n      USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id\n     OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.conversation_id IS DISTINCT FROM NEW.conversation_id\n     OR OLD.turn_id IS DISTINCT FROM NEW.turn_id\n     OR OLD.learning_track_id IS DISTINCT FROM NEW.learning_track_id\n     OR OLD.knowledge_key IS DISTINCT FROM NEW.knowledge_key\n     OR OLD.teaching_session_id IS DISTINCT FROM NEW.teaching_session_id\n     OR OLD.checkpoint_id IS DISTINCT FROM NEW.checkpoint_id\n     OR OLD.track_version IS DISTINCT FROM NEW.track_version\n     OR OLD.progress_version IS DISTINCT FROM NEW.progress_version\n     OR OLD.assignment_version IS DISTINCT FROM NEW.assignment_version\n     OR OLD.owner_kind IS DISTINCT FROM NEW.owner_kind\n     OR OLD.owner_id IS DISTINCT FROM NEW.owner_id\n     OR OLD.artifact_schema_version IS DISTINCT FROM NEW.artifact_schema_version\n     OR OLD.artifact_kind IS DISTINCT FROM NEW.artifact_kind\n     OR OLD.purpose IS DISTINCT FROM NEW.purpose\n     OR OLD.blocking IS DISTINCT FROM NEW.blocking\n     OR OLD.title IS DISTINCT FROM NEW.title\n     OR OLD.instruction_markdown IS DISTINCT FROM NEW.instruction_markdown\n     OR OLD.difficulty IS DISTINCT FROM NEW.difficulty\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Learning Artifact identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('completed', 'failed', 'cancelled', 'superseded') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal Learning Artifact is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.version <> OLD.version + 1 THEN\n    RAISE EXCEPTION 'Learning Artifact version must advance exactly once' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = NEW.state THEN RETURN NEW; END IF;\n  IF OLD.state = 'pending' AND NEW.state IN ('ready', 'failed', 'cancelled', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.state = 'ready' AND NEW.state IN ('active', 'running', 'completed', 'failed', 'cancelled', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.state = 'active' AND NEW.state IN ('running', 'completed', 'failed', 'cancelled', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.state = 'running' AND NEW.state IN ('active', 'completed', 'failed', 'cancelled', 'superseded') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Learning Artifact lifecycle transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_learning_artifact_owner_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  session_row tutor_teaching_sessions%ROWTYPE;\n  gate_row tutor_lesson_gate_states%ROWTYPE;\n  review_item_row tutor_review_items%ROWTYPE;\n  review_session_row tutor_review_sessions%ROWTYPE;\n  item_version_row tutor_learning_item_versions%ROWTYPE;\n  item_publication_row tutor_learning_item_publication_events%ROWTYPE;\n  historical_supersession boolean := false;\n  authority_session_version integer;\nBEGIN\n  SELECT * INTO session_row\n  FROM tutor_teaching_sessions\n  WHERE id=NEW.teaching_session_id\n    AND user_id=NEW.user_id\n    AND conversation_id=NEW.conversation_id\n    AND track_id=NEW.learning_track_id\n    AND knowledge_key=NEW.knowledge_key;\n  -- Only a content-preserving terminal retirement may cross a blocked\n  -- ancestor boundary. All Turn/Attempt/item checks below still run.\n  IF TG_OP='UPDATE' THEN\n   IF OLD.state IN ('pending','ready','active')\n     AND NEW.state='superseded' AND NEW.version=OLD.version+1\n     AND NEW.terminal_at IS NOT NULL AND NEW.allowed_actions_json='[]'::jsonb\n     AND session_row.status='blocked'\n     AND (to_jsonb(NEW)-ARRAY['state','version','terminal_at','updated_at','allowed_actions_json'])\n         IS NOT DISTINCT FROM\n         (to_jsonb(OLD)-ARRAY['state','version','terminal_at','updated_at','allowed_actions_json'])\n     AND EXISTS (\n       SELECT 1 FROM tutor_teaching_session_checkpoints c\n       WHERE c.id=NEW.checkpoint_id AND c.teaching_session_id=NEW.teaching_session_id\n         AND c.user_id=NEW.user_id AND c.conversation_id=NEW.conversation_id\n     )\n     AND (NEW.active_attempt_id IS NULL OR EXISTS (\n       SELECT 1 FROM tutor_exercise_attempt_results r WHERE r.attempt_id=NEW.active_attempt_id\n     ))\n     AND tutor_artifact_supersession_successor(NEW.id) IS NOT NULL THEN\n    historical_supersession := true;\n   END IF;\n  END IF;\n  authority_session_version := session_row.version;\n  IF historical_supersession THEN\n    SELECT session_version INTO authority_session_version\n    FROM tutor_teaching_session_checkpoints WHERE id=NEW.checkpoint_id;\n  END IF;\n  IF NOT historical_supersession AND (session_row.id IS NULL\n     OR session_row.current_checkpoint_id IS DISTINCT FROM NEW.checkpoint_id\n     OR session_row.track_version<>NEW.track_version\n     OR session_row.progress_version<>NEW.progress_version\n     OR session_row.assignment_version<>NEW.assignment_version\n     OR session_row.status NOT IN ('active','paused')) THEN\n    RAISE EXCEPTION 'Learning Artifact teaching authority is stale or mismatched'\n      USING ERRCODE='23514';\n  END IF;\n\n  IF NEW.turn_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n    FROM tutor_run_teaching_scopes AS scopes\n    WHERE scopes.run_id=NEW.turn_id\n      AND scopes.user_id=NEW.user_id\n      AND scopes.conversation_id=NEW.conversation_id\n      AND scopes.teaching_session_id=NEW.teaching_session_id\n      AND scopes.track_id=NEW.learning_track_id\n      AND scopes.knowledge_key=NEW.knowledge_key\n      AND scopes.track_version=NEW.track_version\n      AND scopes.progress_version=NEW.progress_version\n      AND scopes.assignment_version=NEW.assignment_version\n      AND (\n        scopes.checkpoint_id=NEW.checkpoint_id\n        OR EXISTS (\n          SELECT 1\n          FROM tutor_teaching_session_checkpoints AS produced\n          WHERE produced.id=NEW.checkpoint_id\n            AND produced.teaching_session_id=NEW.teaching_session_id\n            AND produced.user_id=NEW.user_id\n            AND produced.conversation_id=NEW.conversation_id\n            AND produced.source_run_id=NEW.turn_id\n            AND produced.predecessor_checkpoint_id=scopes.checkpoint_id\n            AND produced.session_version=scopes.session_version+1\n        )\n      )\n  ) THEN\n    RAISE EXCEPTION 'Learning Artifact Turn scope is stale or mismatched'\n      USING ERRCODE='23514';\n  END IF;\n\n  IF NEW.active_attempt_id IS NOT NULL\n     AND NOT tutor_learning_artifact_attempt_owner_matches(\n       NEW.user_id,\n       NEW.conversation_id,\n       NEW.learning_track_id,\n       NEW.knowledge_key,\n       NEW.teaching_session_id,\n       NEW.owner_kind,\n       NEW.owner_id,\n       NEW.active_attempt_id\n     ) THEN\n    RAISE EXCEPTION 'Learning Artifact active Attempt owner scope is mismatched'\n      USING ERRCODE='23514';\n  END IF;\n\n  IF NEW.owner_kind='lesson_gate' THEN\n    SELECT * INTO gate_row\n    FROM tutor_lesson_gate_states\n    WHERE id=NEW.owner_id\n      AND user_id=NEW.user_id\n      AND track_id=NEW.learning_track_id\n      AND knowledge_key=NEW.knowledge_key\n      AND lesson_assignment_id=session_row.lesson_assignment_id;\n    IF gate_row.id IS NULL\n       OR (NOT historical_supersession AND gate_row.version<>NEW.owner_version)\n       OR NEW.owner_context_version IS NOT NULL THEN\n      RAISE EXCEPTION 'Learning Artifact Lesson Gate owner is stale or mismatched'\n        USING ERRCODE='23514';\n    END IF;\n  ELSIF NEW.owner_kind='review_item' THEN\n    SELECT * INTO review_item_row\n    FROM tutor_review_items\n    WHERE id=NEW.owner_id\n      AND user_id=NEW.user_id\n      AND track_id=NEW.learning_track_id\n      AND knowledge_key=NEW.knowledge_key;\n    IF review_item_row.id IS NULL\n       OR (NOT historical_supersession AND review_item_row.version<>NEW.owner_version) THEN\n      RAISE EXCEPTION 'Learning Artifact Review Item owner is stale or mismatched'\n        USING ERRCODE='23514';\n    END IF;\n    SELECT * INTO review_session_row\n    FROM tutor_review_sessions\n    WHERE id=review_item_row.session_id\n      AND user_id=NEW.user_id\n      AND track_id=NEW.learning_track_id\n      AND knowledge_key=NEW.knowledge_key;\n    IF review_session_row.id IS NULL\n       OR NEW.owner_context_version IS NULL\n       OR (NOT historical_supersession AND review_session_row.version<>NEW.owner_context_version) THEN\n      RAISE EXCEPTION 'Learning Artifact Review Session owner context is stale or mismatched'\n        USING ERRCODE='23514';\n    END IF;\n  ELSIF NEW.owner_kind='teaching_practice' THEN\n    IF NEW.owner_id IS DISTINCT FROM NEW.checkpoint_id\n       OR NEW.owner_version IS DISTINCT FROM authority_session_version\n       OR NEW.owner_context_version IS DISTINCT FROM authority_session_version THEN\n      RAISE EXCEPTION 'Learning Artifact teaching owner is stale or mismatched'\n        USING ERRCODE='23514';\n    END IF;\n  ELSIF NEW.owner_kind='learning_item' THEN\n    SELECT * INTO item_version_row\n    FROM tutor_learning_item_versions\n    WHERE id=NEW.owner_id\n      AND knowledge_key=tutor_plan_catalog_knowledge_key(\n        NEW.user_id, NEW.learning_track_id, session_row.active_plan_revision_id, NEW.knowledge_key\n      );\n    IF item_version_row.id IS NULL\n       OR NEW.owner_context_version IS DISTINCT FROM authority_session_version\n       OR item_version_row.difficulty IS DISTINCT FROM NEW.difficulty\n       OR (NEW.artifact_kind='test_result' AND NEW.purpose<>'result')\n       OR (\n         NEW.artifact_kind<>'test_result'\n         AND (\n           item_version_row.purpose IS DISTINCT FROM NEW.purpose\n           OR (item_version_row.item_kind='code' AND NEW.artifact_kind<>'exercise_workspace')\n           OR (item_version_row.item_kind='sql' AND NEW.artifact_kind<>'sql_workspace')\n           OR (item_version_row.item_kind='demo' AND NEW.artifact_kind<>'demonstration')\n           OR (item_version_row.item_kind='knowledge_check' AND NEW.artifact_kind<>'knowledge_check')\n           OR (item_version_row.item_kind='model_review' AND NEW.artifact_kind<>'model_code_review')\n         )\n       ) THEN\n      RAISE EXCEPTION 'Learning Artifact Learning Item owner is stale or mismatched'\n        USING ERRCODE='23514';\n    END IF;\n    IF item_version_row.item_kind<>'demo' AND NOT EXISTS (\n      SELECT 1\n      FROM tutor_learning_item_practice_materializations AS materializations\n      WHERE materializations.version_id=item_version_row.id\n        AND materializations.item_handle=item_version_row.handle\n        AND materializations.content_hash=item_version_row.content_hash\n    ) THEN\n      RAISE EXCEPTION 'Learning Artifact Learning Item lacks Practice authority'\n        USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='UPDATE'\n       AND NEW.state IN ('completed','failed','cancelled','superseded') THEN\n      IF NEW.owner_version IS DISTINCT FROM OLD.owner_version\n         OR NEW.owner_context_version IS DISTINCT FROM OLD.owner_context_version\n         OR NOT EXISTS (\n           SELECT 1\n           FROM tutor_learning_item_publication_events AS publication\n           WHERE publication.version_id=item_version_row.id\n             AND publication.state_version=NEW.owner_version\n             AND publication.state='published'\n         ) THEN\n        RAISE EXCEPTION 'Learning Artifact terminal Learning Item owner is stale'\n          USING ERRCODE='23514';\n      END IF;\n    ELSE\n      SELECT * INTO item_publication_row\n      FROM tutor_learning_item_publication_events\n      WHERE version_id=item_version_row.id\n      ORDER BY state_version DESC\n      LIMIT 1;\n      IF item_publication_row.id IS NULL\n         OR item_publication_row.state<>'published'\n         OR item_publication_row.state_version<>NEW.owner_version\n         OR item_publication_row.item_handle<>item_version_row.handle\n         OR item_publication_row.content_hash<>item_version_row.content_hash THEN\n        RAISE EXCEPTION 'Learning Artifact Learning Item publication is stale'\n          USING ERRCODE='23514';\n      END IF;\n    END IF;\n  ELSE\n    RAISE EXCEPTION 'Learning Artifact owner kind is invalid' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_learning_item_bank_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION 'Learning Item Bank authority rows are immutable or append-only' USING ERRCODE='23514';\nEND;\n"), ('public.enforce_tutor_learning_plan_draft_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor learning plan drafts are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_learning_track_current_key_active()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF NEW.current_knowledge_key IS NULL THEN\n    RETURN NEW;\n  END IF;\n  IF NOT EXISTS (\n    SELECT 1\n    FROM tutor_track_active_plans AS active\n    JOIN tutor_track_plan_nodes AS nodes\n      ON (nodes.revision_id, nodes.track_id, nodes.user_id) =\n         (active.revision_id, active.track_id, active.user_id)\n    JOIN tutor_track_node_progress AS progress\n      ON (progress.track_id, progress.user_id, progress.knowledge_key) =\n         (nodes.track_id, nodes.user_id, nodes.knowledge_key)\n    WHERE active.track_id = NEW.id\n      AND active.user_id = NEW.user_id\n      AND nodes.knowledge_key = NEW.current_knowledge_key\n  ) THEN\n    RAISE EXCEPTION 'Tutor learning track current key must belong to the active plan' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_lesson_assignment_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Lesson assignments cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.knowledge_key IS DISTINCT FROM OLD.knowledge_key\n     OR NEW.document_id IS DISTINCT FROM OLD.document_id OR NEW.source_plan_revision_id IS DISTINCT FROM OLD.source_plan_revision_id\n     OR NEW.predecessor_assignment_id IS DISTINCT FROM OLD.predecessor_assignment_id\n     OR NEW.assignment_version IS DISTINCT FROM OLD.assignment_version\n     OR NEW.impact_json IS DISTINCT FROM OLD.impact_json OR NEW.content_hash IS DISTINCT FROM OLD.content_hash\n     OR NEW.expected_progress_version IS DISTINCT FROM OLD.expected_progress_version\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Lesson assignment identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at THEN\n    RAISE EXCEPTION 'Started Lesson assignment is frozen' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'active'\n     AND (OLD.activated_at IS NOT NULL OR NEW.activated_at IS NULL) THEN\n    RAISE EXCEPTION 'Activated Lesson assignment requires a new activation timestamp' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status <> 'proposed' AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN\n    RAISE EXCEPTION 'Lesson assignment activation timestamp is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'active' AND NEW.status IN ('active', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.status = 'proposed' AND NEW.status IN ('proposed', 'active', 'superseded') THEN RETURN NEW; END IF;\n  IF OLD.status = NEW.status AND OLD.status = 'superseded' THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Lesson assignment lifecycle transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_lesson_authoring_run_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Lesson authoring runs cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('completed', 'failed', 'cancelled') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal Lesson authoring run is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'pending' AND NEW.state IN ('pending', 'claimed', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'claimed' AND NEW.state IN ('claimed', 'running', 'pending', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'running' AND NEW.state IN ('running', 'completed', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Lesson authoring run lifecycle transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_lesson_authoring_stage_attempt()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE owner_row tutor_lesson_authoring_runs%ROWTYPE; standard_row tutor_lesson_authoring_stage_attempts%ROWTYPE;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Private Lesson stages require confirmed user purge' USING ERRCODE = '23514';\n  END IF;\n  IF TG_OP = 'INSERT' THEN\n    PERFORM pg_advisory_xact_lock(\n      hashtext('lesson-stage:' || NEW.user_id::text || ':' || NEW.track_id::text || ':' || NEW.knowledge_key || ':' || NEW.stage_kind),\n      hashtext(NEW.dependency_hash));\n    IF EXISTS (SELECT 1 FROM tutor_lesson_authoring_stage_attempts\n      WHERE user_id = NEW.user_id AND track_id = NEW.track_id AND knowledge_key = NEW.knowledge_key\n        AND stage_kind = NEW.stage_kind AND dependency_hash = NEW.dependency_hash\n        AND state IN ('intent','outcome_unknown','result_saved','accepted')) THEN\n      RAISE EXCEPTION 'Lesson dependency already has in-flight, unresolved, or accepted work' USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  SELECT * INTO owner_row FROM tutor_lesson_authoring_runs WHERE id = NEW.run_id FOR UPDATE;\n  IF owner_row.id IS NULL OR owner_row.completion_contract_version IS DISTINCT FROM 'lesson_completion_v1'\n     OR (NEW.user_id, NEW.track_id, NEW.knowledge_key) IS DISTINCT FROM (owner_row.user_id, owner_row.track_id, owner_row.knowledge_key) THEN\n    RAISE EXCEPTION 'Lesson stage owner scope mismatch' USING ERRCODE = '23514';\n  END IF;\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.state <> 'intent' OR owner_row.state <> 'running' OR NEW.lease_generation <> owner_row.lease_generation\n       OR owner_row.lease_expires_at <= clock_timestamp() OR NEW.attempt_index <> owner_row.attempt_count + 1\n       OR NEW.dependency_json ->> 'schema_version' IS DISTINCT FROM 'lesson_completion_v1'\n       OR NEW.dependency_json ->> 'user_id' IS DISTINCT FROM NEW.user_id::text\n       OR NEW.dependency_json ->> 'track_id' IS DISTINCT FROM NEW.track_id::text\n       OR NEW.dependency_json ->> 'knowledge_key' IS DISTINCT FROM NEW.knowledge_key\n       OR NEW.dependency_json ->> 'stage_kind' IS DISTINCT FROM NEW.stage_kind\n       OR NEW.dependency_json #>> '{evidence,schema_version}' IS DISTINCT FROM 'lesson_evidence_units_v1'\n       OR NEW.dependency_json #>> '{evidence,legacy_source_set_hash}' IS DISTINCT FROM owner_row.source_set_hash\n       OR jsonb_typeof(NEW.dependency_json #> '{evidence,selected_units}') IS DISTINCT FROM 'array'\n       OR jsonb_array_length(NEW.dependency_json #> '{evidence,selected_units}') = 0 THEN\n      RAISE EXCEPTION 'Lesson intent requires a live explicit owner and complete dependency' USING ERRCODE = '23514';\n    END IF;\n    IF NEW.stage_kind = 'personalized' THEN\n      SELECT * INTO standard_row FROM tutor_lesson_authoring_stage_attempts WHERE id = NEW.standard_attempt_id;\n      IF standard_row.state IS DISTINCT FROM 'accepted' OR standard_row.stage_kind IS DISTINCT FROM 'standard'\n         OR (standard_row.user_id, standard_row.track_id, standard_row.knowledge_key) IS DISTINCT FROM (NEW.user_id, NEW.track_id, NEW.knowledge_key)\n         OR NEW.dependency_json ->> 'standard_dependency_hash' IS DISTINCT FROM standard_row.dependency_hash\n         OR NEW.dependency_json ->> 'standard_document_hash' IS DISTINCT FROM standard_row.document_hash\n         OR NEW.dependency_json ->> 'profile_hash' IS DISTINCT FROM owner_row.profile_hash THEN\n        RAISE EXCEPTION 'Personalization requires an exact accepted private standard' USING ERRCODE = '23514';\n      END IF;\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF OLD.state IN ('accepted', 'rejected', 'outcome_unknown') OR\n     (to_jsonb(NEW) - ARRAY['state','execution_outcome','usage_status','result_json','feedback_json','result_saved_at','result_transaction_id','decision_lease_generation','document_json','document_hash','quality_json','decided_at'])\n       IS DISTINCT FROM\n     (to_jsonb(OLD) - ARRAY['state','execution_outcome','usage_status','result_json','feedback_json','result_saved_at','result_transaction_id','decision_lease_generation','document_json','document_hash','quality_json','decided_at']) THEN\n    RAISE EXCEPTION 'Lesson stage identity/terminal result is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'intent' AND NEW.state IN ('result_saved', 'outcome_unknown') THEN\n    -- Real late results can be saved, but this does not accept them or renew authority.\n    NEW.result_transaction_id := pg_current_xact_id();\n    RETURN NEW;\n  END IF;\n  IF OLD.state = 'result_saved' AND NEW.state IN ('accepted', 'rejected') THEN\n    IF (NEW.execution_outcome, NEW.usage_status, NEW.result_json, NEW.feedback_json, NEW.result_saved_at, NEW.result_transaction_id)\n        IS DISTINCT FROM (OLD.execution_outcome, OLD.usage_status, OLD.result_json, OLD.feedback_json, OLD.result_saved_at, OLD.result_transaction_id)\n       OR owner_row.state <> 'running' OR owner_row.lease_expires_at <= clock_timestamp()\n       OR NEW.decision_lease_generation IS DISTINCT FROM owner_row.lease_generation\n       OR OLD.result_transaction_id = pg_current_xact_id()\n       OR OLD.result_saved_at > OLD.result_deadline_at THEN\n      RAISE EXCEPTION 'Lesson decision cannot alter result DATA or consume an expired owner' USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\n  END IF;\n  RAISE EXCEPTION 'Illegal Lesson completion stage transition' USING ERRCODE = '23514';\nEND "), ('public.enforce_tutor_lesson_document_lineage()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  standard_row tutor_lesson_documents%ROWTYPE;\n  predecessor_row tutor_lesson_documents%ROWTYPE;\nBEGIN\n  IF NEW.document_kind = 'personalized' THEN\n    SELECT * INTO standard_row FROM tutor_lesson_documents WHERE id = NEW.standard_document_id;\n    IF standard_row.id IS NULL OR standard_row.document_kind <> 'standard'\n       OR standard_row.language_id <> NEW.language_id\n       OR standard_row.knowledge_key <> NEW.knowledge_key THEN\n      RAISE EXCEPTION 'Personalized LessonDocument must reference a matching standard document' USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  IF NEW.predecessor_document_id IS NOT NULL THEN\n    SELECT * INTO predecessor_row FROM tutor_lesson_documents WHERE id = NEW.predecessor_document_id;\n    IF predecessor_row.id IS NULL OR predecessor_row.document_kind <> NEW.document_kind\n       OR predecessor_row.language_id <> NEW.language_id\n       OR predecessor_row.knowledge_key <> NEW.knowledge_key\n       OR predecessor_row.user_id IS DISTINCT FROM NEW.user_id\n       OR predecessor_row.track_id IS DISTINCT FROM NEW.track_id THEN\n      RAISE EXCEPTION 'LessonDocument predecessor scope is invalid' USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_lesson_gate_state_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Lesson Gate state cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.knowledge_key IS DISTINCT FROM OLD.knowledge_key\n     OR NEW.lesson_assignment_id IS DISTINCT FROM OLD.lesson_assignment_id\n     OR NEW.document_id IS DISTINCT FROM OLD.document_id OR NEW.gate_binding_id IS DISTINCT FROM OLD.gate_binding_id\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Lesson Gate state identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'passed' AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Passed Lesson Gate state is immutable' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_lesson_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF OLD.user_id IS NOT NULL AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RETURN OLD;\n    END IF;\n    RAISE EXCEPTION 'Lesson authority rows are append-only' USING ERRCODE = '23514';\n  END IF;\n  RAISE EXCEPTION 'Lesson authority rows are immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_mastery_evidence_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor mastery evidence is append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_memory_entry_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    IF OLD.memory_kind IS DISTINCT FROM NEW.memory_kind\n       OR OLD.category IS DISTINCT FROM NEW.category\n       OR OLD.statement IS DISTINCT FROM NEW.statement\n       OR OLD.confidence IS DISTINCT FROM NEW.confidence\n       OR OLD.provenance_kind IS DISTINCT FROM NEW.provenance_kind\n       OR OLD.source_run_id IS DISTINCT FROM NEW.source_run_id\n       OR OLD.source_effect_record_id IS DISTINCT FROM NEW.source_effect_record_id\n       OR OLD.source_outbox_id IS DISTINCT FROM NEW.source_outbox_id\n       OR OLD.source_proposal_id IS DISTINCT FROM NEW.source_proposal_id\n       OR OLD.replaced_entry_id IS DISTINCT FROM NEW.replaced_entry_id\n       OR OLD.evidence_ids_json IS DISTINCT FROM NEW.evidence_ids_json\n       OR OLD.evidence_hashes_json IS DISTINCT FROM NEW.evidence_hashes_json\n       OR OLD.policy_version IS DISTINCT FROM NEW.policy_version\n       OR OLD.memory_setting_version IS DISTINCT FROM NEW.memory_setting_version\n       OR OLD.retention_until IS DISTINCT FROM NEW.retention_until\n       OR OLD.stale_after IS DISTINCT FROM NEW.stale_after\n       OR OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN\n      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor memory evidence is immutable';\n    END IF;\n    IF OLD.state <> 'active' OR NEW.state NOT IN ('corrected', 'deleted', 'expired') THEN\n      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor memory lifecycle transition is invalid';\n    END IF;\n  ELSIF TG_OP = 'DELETE' THEN\n    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor memory entries are not deleted physically';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_message_context_reference_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Tutor message context references are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_model_review_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_model_review_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Model review receipt and publication rows are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_model_review_artifact_receipt_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE artifact_row tutor_learning_artifacts%ROWTYPE;\nDECLARE materialization_row tutor_learning_item_practice_materializations%ROWTYPE;\nBEGIN\n  SELECT * INTO artifact_row FROM tutor_learning_artifacts\n  WHERE id=NEW.artifact_id AND user_id=NEW.user_id AND conversation_id=NEW.conversation_id\n    AND teaching_session_id=NEW.teaching_session_id AND learning_track_id=NEW.learning_track_id\n    AND knowledge_key=NEW.knowledge_key FOR UPDATE;\n  SELECT * INTO materialization_row FROM tutor_learning_item_practice_materializations\n  WHERE version_id=NEW.learning_item_version_id;\n  IF artifact_row.id IS NULL\n     OR artifact_row.artifact_kind<>'model_code_review'\n     OR artifact_row.presentation_kind<>'model_code_review_v2'\n     OR artifact_row.state NOT IN ('ready','active')\n     OR artifact_row.version<>NEW.artifact_version\n     OR artifact_row.owner_kind<>'learning_item'\n     OR artifact_row.owner_id<>NEW.learning_item_version_id\n     OR artifact_row.checkpoint_id<>NEW.checkpoint_id\n     OR materialization_row.version_id IS NULL\n     OR materialization_row.exercise_version_id<>NEW.exercise_version_id\n     OR materialization_row.item_handle IS NULL THEN\n    RAISE EXCEPTION 'Model review Artifact receipt scope is stale or mismatched' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_model_review_authoring_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_model_review_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Model review authoring run cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.track_id IS DISTINCT FROM NEW.track_id OR OLD.knowledge_key IS DISTINCT FROM NEW.knowledge_key\n     OR OLD.plan_revision_id IS DISTINCT FROM NEW.plan_revision_id\n     OR OLD.lesson_assignment_id IS DISTINCT FROM NEW.lesson_assignment_id\n     OR OLD.document_id IS DISTINCT FROM NEW.document_id OR OLD.slot_id IS DISTINCT FROM NEW.slot_id\n     OR OLD.gate_key IS DISTINCT FROM NEW.gate_key\n     OR OLD.expected_track_version IS DISTINCT FROM NEW.expected_track_version\n     OR OLD.expected_progress_version IS DISTINCT FROM NEW.expected_progress_version\n     OR OLD.expected_assignment_version IS DISTINCT FROM NEW.expected_assignment_version\n     OR OLD.language_id IS DISTINCT FROM NEW.language_id\n     OR OLD.required_capabilities_json IS DISTINCT FROM NEW.required_capabilities_json\n     OR OLD.mastery_level IS DISTINCT FROM NEW.mastery_level\n     OR OLD.mastery_confidence IS DISTINCT FROM NEW.mastery_confidence\n     OR OLD.misconception_tags_json IS DISTINCT FROM NEW.misconception_tags_json\n     OR OLD.validation_profile_version IS DISTINCT FROM NEW.validation_profile_version\n     OR OLD.request_hash IS DISTINCT FROM NEW.request_hash OR OLD.profile_hash IS DISTINCT FROM NEW.profile_hash\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Model review authoring identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('completed', 'failed', 'cancelled') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal model review authoring run is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = NEW.state THEN RETURN NEW; END IF;\n  IF OLD.state = 'pending' AND NEW.state IN ('claimed', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'claimed' AND NEW.state IN ('running', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'running' AND NEW.state IN ('validating', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'validating' AND NEW.state IN ('completed', 'failed', 'cancelled') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Model review authoring transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_model_review_candidate_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_model_review_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Model review candidate cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id OR OLD.authoring_run_id IS DISTINCT FROM NEW.authoring_run_id\n     OR OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.track_id IS DISTINCT FROM NEW.track_id\n     OR OLD.knowledge_key IS DISTINCT FROM NEW.knowledge_key\n     OR OLD.public_payload_json IS DISTINCT FROM NEW.public_payload_json\n     OR OLD.private_payload_json IS DISTINCT FROM NEW.private_payload_json\n     OR OLD.public_hash IS DISTINCT FROM NEW.public_hash OR OLD.private_hash IS DISTINCT FROM NEW.private_hash\n     OR OLD.candidate_hash IS DISTINCT FROM NEW.candidate_hash\n     OR OLD.generator_version IS DISTINCT FROM NEW.generator_version\n     OR OLD.prompt_schema_version IS DISTINCT FROM NEW.prompt_schema_version\n     OR OLD.validation_profile_version IS DISTINCT FROM NEW.validation_profile_version\n     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Model review candidate payload is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('rejected', 'published') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal model review candidate is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = NEW.state THEN RETURN NEW; END IF;\n  IF OLD.state = 'draft' AND NEW.state IN ('validating', 'rejected') THEN RETURN NEW; END IF;\n  IF OLD.state = 'validating' AND NEW.state IN ('verified', 'rejected') THEN RETURN NEW; END IF;\n  IF OLD.state = 'verified' AND NEW.state IN ('published', 'rejected') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Model review candidate transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_model_review_validation_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_model_review_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Model review validation run cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.id IS DISTINCT FROM NEW.id OR OLD.authoring_run_id IS DISTINCT FROM NEW.authoring_run_id\n     OR OLD.candidate_id IS DISTINCT FROM NEW.candidate_id OR OLD.user_id IS DISTINCT FROM NEW.user_id\n     OR OLD.track_id IS DISTINCT FROM NEW.track_id\n     OR OLD.validation_profile_version IS DISTINCT FROM NEW.validation_profile_version\n     OR OLD.candidate_hash IS DISTINCT FROM NEW.candidate_hash OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION 'Model review validation identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'verified' AND NEW.state = 'verified'\n     AND OLD.action_receipt_hash IS NULL AND NEW.action_receipt_hash IS NOT NULL\n     AND OLD.id IS NOT DISTINCT FROM NEW.id\n     AND OLD.authoring_run_id IS NOT DISTINCT FROM NEW.authoring_run_id\n     AND OLD.candidate_id IS NOT DISTINCT FROM NEW.candidate_id\n     AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id\n     AND OLD.track_id IS NOT DISTINCT FROM NEW.track_id\n     AND OLD.validation_profile_version IS NOT DISTINCT FROM NEW.validation_profile_version\n     AND OLD.candidate_hash IS NOT DISTINCT FROM NEW.candidate_hash\n     AND OLD.action_invocation_id IS NOT DISTINCT FROM NEW.action_invocation_id\n     AND OLD.authority_hash IS NOT DISTINCT FROM NEW.authority_hash\n     AND OLD.check_summary_code IS NOT DISTINCT FROM NEW.check_summary_code\n     AND OLD.failure_code IS NOT DISTINCT FROM NEW.failure_code\n     AND OLD.safe_summary IS NOT DISTINCT FROM NEW.safe_summary\n     AND OLD.terminal_at IS NOT DISTINCT FROM NEW.terminal_at\n     AND OLD.created_at IS NOT DISTINCT FROM NEW.created_at THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.state IN ('verified', 'failed', 'stale') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal model review validation run is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = NEW.state THEN RETURN NEW; END IF;\n  IF OLD.state = 'pending' AND NEW.state IN ('running', 'failed', 'stale') THEN RETURN NEW; END IF;\n  IF OLD.state = 'running' AND NEW.state IN ('verified', 'failed', 'stale') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Model review validation transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_module_diagnostic_session_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Module diagnostic session cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.module_key IS DISTINCT FROM OLD.module_key\n     OR NEW.diagnostic_version_id IS DISTINCT FROM OLD.diagnostic_version_id\n     OR NEW.source_plan_revision_id IS DISTINCT FROM OLD.source_plan_revision_id\n     OR NEW.expected_track_version IS DISTINCT FROM OLD.expected_track_version\n     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key OR NEW.request_hash IS DISTINCT FROM OLD.request_hash\n     OR NEW.started_at IS DISTINCT FROM OLD.started_at OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Module diagnostic session identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('failed', 'confirmed', 'expired') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal module diagnostic session is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'active' AND NEW.state IN ('active', 'failed', 'passed_pending_confirmation', 'expired') THEN RETURN NEW; END IF;\n  IF OLD.state = 'passed_pending_confirmation' AND NEW.state IN ('passed_pending_confirmation', 'confirmed', 'expired') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Module diagnostic session transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_plan_action_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor plan revision actions are append-only';\nEND;\n"), ('public.enforce_tutor_plan_catalog_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  source_node jsonb;\n  language_key text;\nBEGIN\n  IF NEW.catalog_knowledge_key IS NULL THEN RETURN NEW; END IF;\n  SELECT n INTO source_node FROM tutor_track_plan_revisions revisions\n    CROSS JOIN LATERAL jsonb_array_elements(revisions.plan_json->'modules') m\n    CROSS JOIN LATERAL jsonb_array_elements(m->'nodes') n\n    WHERE revisions.id=NEW.revision_id AND revisions.user_id=NEW.user_id\n      AND revisions.track_id=NEW.track_id AND n->>'knowledge_key'=NEW.knowledge_key;\n  IF source_node IS NULL OR source_node->>'catalog_knowledge_key' IS DISTINCT FROM NEW.catalog_knowledge_key\n     OR source_node->'required_capabilities' IS DISTINCT FROM NEW.required_capabilities_json THEN\n    RAISE EXCEPTION 'Plan catalog mapping must match the immutable plan payload' USING ERRCODE='23514';\n  END IF;\n  SELECT language_id INTO language_key FROM tutor_learning_tracks\n    WHERE id=NEW.track_id AND user_id=NEW.user_id;\n  IF NOT EXISTS (\n    SELECT 1 FROM tutor_learning_item_versions versions\n    JOIN LATERAL (SELECT state FROM tutor_learning_item_publication_events publication\n      WHERE publication.version_id=versions.id ORDER BY state_version DESC LIMIT 1) pub ON pub.state='published'\n    WHERE versions.knowledge_key=NEW.catalog_knowledge_key AND versions.language_id=language_key\n      AND versions.required_capabilities_json <@ NEW.required_capabilities_json\n  ) THEN\n    RAISE EXCEPTION 'Plan catalog mapping has no published compatible content' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_plan_revision_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Tutor plan revisions are immutable';\nEND;\n"), ('public.enforce_tutor_review_schedule_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Review schedule cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.knowledge_key IS DISTINCT FROM OLD.knowledge_key\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Review schedule identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.version <> OLD.version + 1 THEN\n    RAISE EXCEPTION 'Review schedule version must advance exactly once' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_review_session_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Review session cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.plan_revision_id IS DISTINCT FROM OLD.plan_revision_id\n     OR NEW.knowledge_key IS DISTINCT FROM OLD.knowledge_key\n     OR NEW.expected_track_version IS DISTINCT FROM OLD.expected_track_version\n     OR NEW.expected_schedule_version IS DISTINCT FROM OLD.expected_schedule_version\n     OR NEW.context_snapshot_json IS DISTINCT FROM OLD.context_snapshot_json\n     OR NEW.context_snapshot_hash IS DISTINCT FROM OLD.context_snapshot_hash\n     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key\n     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash\n     OR NEW.started_at IS DISTINCT FROM OLD.started_at OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Review session identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('finalized', 'cancelled') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal review session is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.version <> OLD.version + 1 THEN\n    RAISE EXCEPTION 'Review session version must advance exactly once' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'blocked' AND NEW.state IN ('blocked', 'active', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'active' AND NEW.state IN ('active', 'ready_to_finalize', 'cancelled') THEN RETURN NEW; END IF;\n  IF OLD.state = 'ready_to_finalize' AND NEW.state IN ('active', 'ready_to_finalize', 'finalized', 'cancelled') THEN RETURN NEW; END IF;\n  RAISE EXCEPTION 'Review session transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_run_branch_scope()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  branch_row tutor_conversation_branches%ROWTYPE;\nBEGIN\n  IF TG_OP <> 'INSERT' THEN\n    IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RETURN OLD;\n    END IF;\n    RAISE EXCEPTION 'Tutor run branch scope is immutable' USING ERRCODE = '23514';\n  END IF;\n  SELECT * INTO branch_row\n  FROM tutor_conversation_branches\n  WHERE id = NEW.branch_id\n    AND user_id = NEW.user_id\n    AND conversation_id = NEW.conversation_id\n    AND artifact_id = NEW.artifact_id;\n  IF branch_row.id IS NULL OR branch_row.state <> 'active'\n     OR branch_row.version <> NEW.branch_version\n     OR branch_row.round_count <> NEW.branch_round\n     OR branch_row.teaching_session_id <> NEW.teaching_session_id\n     OR NOT tutor_teaching_checkpoint_descends_from(\n       NEW.checkpoint_id, branch_row.checkpoint_id,\n       NEW.teaching_session_id, NEW.user_id, NEW.conversation_id\n     )\n     OR branch_row.learning_track_id <> NEW.learning_track_id\n     OR branch_row.knowledge_key <> NEW.knowledge_key THEN\n    RAISE EXCEPTION 'Tutor run branch scope is stale or mismatched'\n      USING ERRCODE = '23514';\n  END IF;\n  IF NEW.control_kind = 'confirm_topic_switch'\n     AND branch_row.latest_disposition IS DISTINCT FROM 'offer_switch' THEN\n    RAISE EXCEPTION 'Tutor topic switch confirmation has no pending offer'\n      USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_run_execution_batch()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  r tutor_runs%ROWTYPE;\n  p tutor_run_execution_batches%ROWTYPE;\n  t timestamptz;\nBEGIN\n  -- Forward protection only: no legacy UPDATE can opt an existing run into B.\n  IF TG_TABLE_NAME='tutor_runs' THEN\n    IF OLD.policy_json->>'execution_profile'='completion_driven_v1' AND\n       (NEW.iteration_count<OLD.iteration_count OR NEW.model_call_count<OLD.model_call_count\n        OR NEW.capability_call_count<OLD.capability_call_count OR NEW.effect_count<OLD.effect_count) THEN\n      RAISE check_violation USING MESSAGE='completion cumulative counters cannot decrease';\n    END IF;\n    IF (OLD.policy_json->>'execution_profile'='completion_driven_v1'\n        OR NEW.policy_json->>'execution_profile'='completion_driven_v1')\n       AND (NEW.policy_json IS DISTINCT FROM OLD.policy_json\n        OR NEW.policy_version IS DISTINCT FROM OLD.policy_version\n        OR NEW.policy_fingerprint IS DISTINCT FROM OLD.policy_fingerprint\n        OR NEW.user_id IS DISTINCT FROM OLD.user_id\n        OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n        OR NEW.catalog_digest IS DISTINCT FROM OLD.catalog_digest) THEN\n      RAISE check_violation USING MESSAGE='completion run policy and scope are immutable';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF TG_OP='DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE check_violation USING MESSAGE='completion batch deletion denied';\n  END IF;\n  IF TG_OP='UPDATE' THEN\n    SELECT * INTO r FROM tutor_runs WHERE id=OLD.run_id FOR UPDATE;\n    t:=clock_timestamp();\n    IF NOT FOUND OR r.terminal_outcome IS NOT NULL OR r.cancelled_at IS NOT NULL\n       OR r.superseded_by_run_id IS NOT NULL OR r.input_revision<>OLD.input_revision\n       OR r.active_lease_owner_id IS DISTINCT FROM OLD.owner_id\n       OR r.active_lease_generation<>OLD.owner_generation\n       OR r.active_lease_expires_at IS NULL OR r.active_lease_expires_at<=t THEN\n      RAISE check_violation USING MESSAGE='completion batch accounting current owner required';\n    END IF;\n    IF (to_jsonb(NEW)-ARRAY['decision_count','http_attempt_count']) IS DISTINCT FROM\n       (to_jsonb(OLD)-ARRAY['decision_count','http_attempt_count'])\n       OR NEW.decision_count NOT BETWEEN OLD.decision_count AND OLD.decision_count+1\n       OR NEW.http_attempt_count NOT BETWEEN OLD.http_attempt_count AND OLD.http_attempt_count+1 THEN\n      RAISE check_violation USING MESSAGE='completion batch identity and accounting immutable';\n    END IF;\n    -- A send cannot consume the result reserve. Counters never reset on rollover.\n    IF clock_timestamp() >= OLD.expires_at - make_interval(secs=>OLD.result_reserve_seconds) THEN\n      RAISE check_violation USING MESSAGE='completion batch send window expired';\n    END IF;\n    RETURN NEW;\n  END IF;\n  SELECT * INTO r FROM tutor_runs WHERE id=NEW.run_id FOR UPDATE;\n  t:=clock_timestamp();\n  IF NOT FOUND OR r.user_id<>NEW.user_id OR r.conversation_id<>NEW.conversation_id\n     OR r.input_revision<>NEW.input_revision\n     OR r.policy_json->>'execution_profile' IS DISTINCT FROM 'completion_driven_v1'\n     OR r.policy_version IS DISTINCT FROM 'tutor_completion_driven_v1'\n     OR r.policy_fingerprint IS DISTINCT FROM NEW.policy_fingerprint\n     OR r.terminal_outcome IS NOT NULL OR r.cancelled_at IS NOT NULL OR r.superseded_by_run_id IS NOT NULL\n     OR r.active_lease_owner_id IS DISTINCT FROM NEW.owner_id\n     OR r.active_lease_generation<>NEW.owner_generation\n     OR r.active_lease_expires_at IS NULL OR r.active_lease_expires_at<=t\n     OR NEW.issued_at>t OR NEW.issued_at<t-interval '5 seconds'\n     OR NEW.decision_count<>0 OR NEW.http_attempt_count<>0 THEN\n    RAISE check_violation USING MESSAGE='completion batch current owner required';\n  END IF;\n  IF EXISTS (SELECT 1 FROM tutor_run_step_attempts WHERE run_id=NEW.run_id\n      AND state IN ('prepared','dispatched','outcome_unknown')) THEN\n    RAISE check_violation USING MESSAGE='completion unresolved attempt blocks successor';\n  END IF;\n  IF NEW.predecessor_batch_id IS NULL THEN\n    IF NEW.batch_index<>1 THEN RAISE check_violation USING MESSAGE='completion batch root invalid'; END IF;\n  ELSE\n    SELECT * INTO p FROM tutor_run_execution_batches WHERE id=NEW.predecessor_batch_id FOR UPDATE;\n    IF NOT FOUND OR p.run_id<>NEW.run_id OR NEW.batch_index<>p.batch_index+1\n       OR p.input_revision<>NEW.input_revision OR p.policy_fingerprint<>NEW.policy_fingerprint THEN\n      RAISE check_violation USING MESSAGE='completion batch predecessor invalid';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_run_learning_scope_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor run learning scope is immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_run_runtime_kind_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF NEW.runtime_kind IS DISTINCT FROM OLD.runtime_kind THEN\n    RAISE EXCEPTION 'Tutor run runtime kind is immutable' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_run_step_attempt()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  r tutor_runs%ROWTYPE;\n  b tutor_run_execution_batches%ROWTYPE;\n  p tutor_run_step_attempts%ROWTYPE;\n  t timestamptz;\nBEGIN\n  IF TG_OP='DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE check_violation USING MESSAGE='completion step deletion denied';\n  END IF;\n  IF TG_OP='UPDATE' THEN\n    IF (to_jsonb(NEW)-ARRAY['state','dispatched_at','observable_http_count','http_batch_ids_json','result_type','result_json',\n        'result_recorded_at','accepted_at','accepted_owner_id','accepted_owner_generation','acceptance_batch_id','diagnostic_code'])\n       IS DISTINCT FROM\n       (to_jsonb(OLD)-ARRAY['state','dispatched_at','observable_http_count','http_batch_ids_json','result_type','result_json',\n        'result_recorded_at','accepted_at','accepted_owner_id','accepted_owner_generation','acceptance_batch_id','diagnostic_code']) THEN\n      RAISE check_violation USING MESSAGE='completion step identity immutable';\n    END IF;\n    IF OLD.state IN ('accepted','rejected','not_sent','outcome_unknown') THEN\n      IF NEW IS DISTINCT FROM OLD THEN RAISE check_violation USING MESSAGE='completion final result immutable'; END IF;\n      RETURN NEW;\n    END IF;\n    IF OLD.result_json IS NOT NULL AND\n       (NEW.result_json IS DISTINCT FROM OLD.result_json OR NEW.result_type IS DISTINCT FROM OLD.result_type\n        OR NEW.result_recorded_at IS DISTINCT FROM OLD.result_recorded_at) THEN\n      RAISE check_violation USING MESSAGE='completion recorded result immutable';\n    END IF;\n    IF OLD.dispatched_at IS NOT NULL AND NEW.dispatched_at IS DISTINCT FROM OLD.dispatched_at THEN\n      RAISE check_violation USING MESSAGE='completion dispatch immutable';\n    END IF;\n    IF NOT ((OLD.state='prepared' AND NEW.state IN ('not_sent','dispatched'))\n        OR (OLD.state='dispatched' AND NEW.state IN ('dispatched','result_recorded','outcome_unknown'))\n        OR (OLD.state='result_recorded' AND NEW.state IN ('result_recorded','accepted','rejected'))) THEN\n      RAISE check_violation USING MESSAGE='completion step transition invalid';\n    END IF;\n    IF NEW.observable_http_count NOT BETWEEN OLD.observable_http_count AND OLD.observable_http_count+1\n       OR (NEW.observable_http_count<>OLD.observable_http_count AND\n           (OLD.state NOT IN ('dispatched','result_recorded') OR NEW.state<>OLD.state))\n       OR (NEW.observable_http_count=OLD.observable_http_count AND NEW.http_batch_ids_json<>OLD.http_batch_ids_json)\n       OR (NEW.observable_http_count=OLD.observable_http_count+1 AND\n           (NEW.http_batch_ids_json - (jsonb_array_length(NEW.http_batch_ids_json)-1))<>OLD.http_batch_ids_json) THEN\n      RAISE check_violation USING MESSAGE='completion HTTP accounting invalid';\n    END IF;\n    -- Recording the original sent outcome is allowed after cancellation/takeover.\n    -- This is private DATA only; it grants no business acceptance or retry.\n    IF OLD.state='dispatched' AND NEW.state IN ('result_recorded','outcome_unknown') THEN RETURN NEW; END IF;\n  END IF;\n  SELECT * INTO r FROM tutor_runs WHERE id=NEW.run_id FOR UPDATE;\n  t:=clock_timestamp();\n  IF NOT FOUND OR r.user_id<>NEW.user_id OR r.conversation_id<>NEW.conversation_id\n     OR r.input_revision<>NEW.input_revision\n     OR r.policy_json->>'execution_profile' IS DISTINCT FROM 'completion_driven_v1'\n     OR r.policy_version IS DISTINCT FROM 'tutor_completion_driven_v1'\n     OR r.terminal_outcome IS NOT NULL OR r.cancelled_at IS NOT NULL OR r.superseded_by_run_id IS NOT NULL\n     OR r.active_lease_expires_at IS NULL OR r.active_lease_expires_at<=t THEN\n    RAISE check_violation USING MESSAGE='completion step current scope required';\n  END IF;\n  IF NEW.state='accepted' THEN\n    SELECT * INTO b FROM tutor_run_execution_batches WHERE id=NEW.acceptance_batch_id FOR UPDATE;\n    t:=clock_timestamp();\n    IF NOT FOUND OR b.run_id<>r.id OR b.input_revision<>r.input_revision OR b.expires_at<=t\n       OR b.owner_id IS DISTINCT FROM r.active_lease_owner_id OR b.owner_generation<>r.active_lease_generation\n       OR NEW.accepted_owner_id IS DISTINCT FROM r.active_lease_owner_id\n       OR NEW.accepted_owner_generation<>r.active_lease_generation OR r.active_lease_expires_at<=t THEN\n      RAISE check_violation USING MESSAGE='completion fresh acceptance batch required';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF NEW.state IN ('not_sent','rejected') THEN RETURN NEW; END IF;\n  IF TG_OP='UPDATE' AND NEW.observable_http_count<>OLD.observable_http_count THEN\n    SELECT * INTO b FROM tutor_run_execution_batches\n      WHERE id=(NEW.http_batch_ids_json->>-1)::uuid FOR UPDATE;\n    t:=clock_timestamp();\n    IF NOT FOUND OR b.run_id<>r.id OR b.input_revision<>r.input_revision\n       OR b.owner_id IS DISTINCT FROM r.active_lease_owner_id OR b.owner_generation<>r.active_lease_generation\n       OR b.expires_at<=t+make_interval(secs=>b.result_reserve_seconds) OR r.active_lease_expires_at<=t\n       OR (OLD.state='dispatched' AND (NEW.owner_id IS DISTINCT FROM r.active_lease_owner_id\n            OR NEW.owner_generation<>r.active_lease_generation OR b.id<>NEW.batch_id)) THEN\n      RAISE check_violation USING MESSAGE='completion observable HTTP current batch required';\n    END IF;\n    UPDATE tutor_run_execution_batches SET http_attempt_count=http_attempt_count+1 WHERE id=b.id;\n    RETURN NEW;\n  END IF;\n  IF NEW.owner_id IS DISTINCT FROM r.active_lease_owner_id OR NEW.owner_generation<>r.active_lease_generation THEN\n    RAISE check_violation USING MESSAGE='completion dispatch owner replaced';\n  END IF;\n  SELECT * INTO b FROM tutor_run_execution_batches WHERE id=NEW.batch_id FOR UPDATE;\n  t:=clock_timestamp();\n  IF NOT FOUND OR b.run_id<>r.id OR b.input_revision<>r.input_revision\n     OR b.owner_id<>NEW.owner_id OR b.owner_generation<>NEW.owner_generation\n     OR b.expires_at<=t+make_interval(secs=>b.result_reserve_seconds) OR r.active_lease_expires_at<=t THEN\n    RAISE check_violation USING MESSAGE='completion batch dispatch expired';\n  END IF;\n  IF TG_OP='INSERT' THEN\n    IF NEW.state<>'prepared' OR NEW.observable_http_count<>0 OR NEW.prepared_at>t\n       OR NEW.prepared_at<t-interval '5 seconds' OR b.decision_count>=b.max_decisions\n       OR b.http_attempt_count>=b.max_http_attempts\n       OR NEW.capability_count_before<>r.capability_call_count OR NEW.effect_count_before<>r.effect_count THEN\n      RAISE check_violation USING MESSAGE='completion preparation invalid';\n    END IF;\n    IF NEW.predecessor_attempt_id IS NULL THEN\n      IF NEW.attempt_number<>1 OR NEW.decision_iteration<>r.model_call_count+1 THEN\n        RAISE check_violation USING MESSAGE='completion step root invalid';\n      END IF;\n    ELSE\n      SELECT * INTO p FROM tutor_run_step_attempts WHERE id=NEW.predecessor_attempt_id FOR UPDATE;\n      IF NOT FOUND OR p.state<>'not_sent' OR p.run_id<>NEW.run_id OR p.step_key<>NEW.step_key\n         OR p.kind<>NEW.kind OR p.decision_iteration<>NEW.decision_iteration\n         OR NEW.attempt_number<>p.attempt_number+1 OR p.request_json<>NEW.request_json\n         OR p.dependencies_json<>NEW.dependencies_json THEN\n        RAISE check_violation USING MESSAGE='completion no-send predecessor required';\n      END IF;\n    END IF;\n  ELSIF OLD.state='prepared' AND NEW.state='dispatched' THEN\n    UPDATE tutor_run_execution_batches SET decision_count=decision_count+1 WHERE id=NEW.batch_id;\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_runtime_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Tutor runtime receipts and public errors are append-only' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_runtime_binding_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  run_profile text;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor runtime bindings are retained audit state' USING ERRCODE = '23514';\n  END IF;\n  IF TG_OP = 'INSERT' THEN\n    SELECT policy_json->>'execution_profile' INTO run_profile\n    FROM tutor_runs WHERE id = NEW.run_id AND user_id = NEW.user_id\n      AND conversation_id = NEW.conversation_id FOR UPDATE;\n    IF (NEW.step_attempt_id IS NOT NULL) IS DISTINCT FROM\n       (COALESCE(run_profile, '') = 'completion_driven_v1') THEN\n      RAISE EXCEPTION 'Tutor runtime step binding requires the frozen completion profile'\n        USING ERRCODE = '23514';\n    END IF;\n    IF EXISTS (\n      SELECT 1 FROM tutor_run_runtime_bindings\n      WHERE run_id = NEW.run_id\n        AND (step_attempt_id IS NULL) IS DISTINCT FROM (NEW.step_attempt_id IS NULL)\n    ) THEN\n      RAISE EXCEPTION 'Legacy and completion runtime bindings cannot be mixed'\n        USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF NEW.run_id IS DISTINCT FROM OLD.run_id\n     OR NEW.step_attempt_id IS DISTINCT FROM OLD.step_attempt_id\n     OR NEW.conversation_runtime_thread_id IS DISTINCT FROM OLD.conversation_runtime_thread_id\n     OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n     OR NEW.runtime_kind IS DISTINCT FROM OLD.runtime_kind\n     OR NEW.runtime_version IS DISTINCT FROM OLD.runtime_version\n     OR NEW.protocol_version IS DISTINCT FROM OLD.protocol_version\n     OR NEW.external_thread_id IS DISTINCT FROM OLD.external_thread_id\n     OR NEW.connection_generation IS DISTINCT FROM OLD.connection_generation\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at\n     OR (OLD.external_turn_id IS NOT NULL AND NEW.external_turn_id IS DISTINCT FROM OLD.external_turn_id) THEN\n    RAISE EXCEPTION 'Tutor runtime binding identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state IN ('completed', 'interrupted', 'unavailable', 'failed') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Tutor runtime terminal binding is immutable' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_runtime_text_item_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor runtime text items are private retained state' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id\n     OR NEW.binding_id IS DISTINCT FROM OLD.binding_id\n     OR NEW.conversation_runtime_thread_id IS DISTINCT FROM OLD.conversation_runtime_thread_id\n     OR NEW.run_id IS DISTINCT FROM OLD.run_id\n     OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n     OR NEW.external_item_hash IS DISTINCT FROM OLD.external_item_hash\n     OR NEW.channel IS DISTINCT FROM OLD.channel\n     OR NEW.connection_generation IS DISTINCT FROM OLD.connection_generation\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Tutor runtime text item identity is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.state = 'completed'\n     AND OLD.public_message_id IS NULL\n     AND NEW.public_message_id IS NOT NULL\n     AND NEW.state IS NOT DISTINCT FROM OLD.state\n     AND NEW.text IS NOT DISTINCT FROM OLD.text\n     AND NEW.last_event_sequence IS NOT DISTINCT FROM OLD.last_event_sequence\n     AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash\n     AND NEW.completed_at IS NOT DISTINCT FROM OLD.completed_at THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.state IN ('completed', 'discarded', 'blocked') AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Terminal Tutor runtime text item is immutable' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_teaching_append_only()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP='DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n  RAISE EXCEPTION 'Tutor teaching authority evidence is append-only' USING ERRCODE='23514';\nEND;\n"), ('public.enforce_tutor_teaching_session_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP='DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN RETURN OLD; END IF;\n    RAISE EXCEPTION 'Tutor teaching sessions cannot be deleted' USING ERRCODE='23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n    OR NEW.track_id IS DISTINCT FROM OLD.track_id OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n    OR NEW.knowledge_key IS DISTINCT FROM OLD.knowledge_key\n    OR NEW.active_plan_revision_id IS DISTINCT FROM OLD.active_plan_revision_id\n    OR NEW.progress_version IS DISTINCT FROM OLD.progress_version\n    OR NEW.lesson_assignment_id IS DISTINCT FROM OLD.lesson_assignment_id\n    OR NEW.assignment_version IS DISTINCT FROM OLD.assignment_version\n    OR NEW.document_id IS DISTINCT FROM OLD.document_id\n    OR NEW.document_content_hash IS DISTINCT FROM OLD.document_content_hash\n    OR NEW.predecessor_session_id IS DISTINCT FROM OLD.predecessor_session_id\n    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Tutor teaching session authority is immutable' USING ERRCODE='23514';\n  END IF;\n  IF NEW.version NOT IN (OLD.version,OLD.version+1) THEN\n    RAISE EXCEPTION 'Tutor teaching session version must advance by one' USING ERRCODE='23514';\n  END IF;\n  IF NEW IS DISTINCT FROM OLD AND NEW.version=OLD.version\n    AND NOT (OLD.current_checkpoint_id IS NULL AND NEW.current_checkpoint_id IS NOT NULL AND OLD.version=1) THEN\n    RAISE EXCEPTION 'Tutor teaching session mutation requires version advance' USING ERRCODE='23514';\n  END IF;\n  IF OLD.status='completed' AND NEW IS DISTINCT FROM OLD THEN\n    RAISE EXCEPTION 'Completed Tutor teaching session is immutable' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_track_active_plan_consistency()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE\n  target_track_id uuid;\n  target_user_id uuid;\n  target_revision_id uuid;\n  target_status text;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RETURN OLD;\n    END IF;\n    RAISE EXCEPTION 'Tutor track active pointer cannot be deleted' USING ERRCODE = '23514';\n  END IF;\n  IF TG_TABLE_NAME = 'tutor_track_active_plans' THEN\n    target_track_id := NEW.track_id;\n    target_user_id := NEW.user_id;\n    target_revision_id := NEW.revision_id;\n    SELECT status INTO target_status\n    FROM tutor_track_plan_revisions\n    WHERE id = target_revision_id AND track_id = target_track_id AND user_id = target_user_id;\n    IF target_status IS DISTINCT FROM 'active' THEN\n      RAISE EXCEPTION 'Tutor track active pointer must reference an active revision' USING ERRCODE = '23514';\n    END IF;\n  ELSE\n    target_track_id := NEW.track_id;\n    target_user_id := NEW.user_id;\n    target_revision_id := NEW.id;\n    target_status := NEW.status;\n    IF target_status = 'active' AND NOT EXISTS (\n      SELECT 1 FROM tutor_track_active_plans\n      WHERE track_id = target_track_id AND user_id = target_user_id AND revision_id = target_revision_id\n    ) THEN\n      RAISE EXCEPTION 'Active Tutor track revision must be the active pointer' USING ERRCODE = '23514';\n    END IF;\n    IF target_status <> 'active' AND EXISTS (\n      SELECT 1 FROM tutor_track_active_plans\n      WHERE track_id = target_track_id AND user_id = target_user_id AND revision_id = target_revision_id\n    ) THEN\n      RAISE EXCEPTION 'Tutor track active pointer cannot reference a non-active revision' USING ERRCODE = '23514';\n    END IF;\n  END IF;\n  IF target_status = 'active' AND EXISTS (\n    SELECT 1\n    FROM tutor_learning_tracks AS tracks\n    WHERE tracks.id = target_track_id\n      AND tracks.user_id = target_user_id\n      AND tracks.current_knowledge_key IS NOT NULL\n      AND NOT EXISTS (\n        SELECT 1 FROM tutor_track_plan_nodes AS nodes\n        WHERE nodes.revision_id = target_revision_id\n          AND nodes.track_id = target_track_id\n          AND nodes.user_id = target_user_id\n          AND nodes.knowledge_key = tracks.current_knowledge_key\n      )\n  ) THEN\n    RAISE EXCEPTION 'Tutor learning track current key must belong to the active revision' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_track_plan_migration_lifecycle()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.status = 'proposed' AND NEW.confirmed_at IS NULL AND NEW.applied_at IS NULL THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION 'Tutor track plan migration initial lifecycle is invalid' USING ERRCODE = '23514';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    IF tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RETURN OLD;\n    END IF;\n    RAISE EXCEPTION 'Tutor track plan migration evidence is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id\n     OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.from_revision_id IS DISTINCT FROM OLD.from_revision_id\n     OR NEW.to_revision_id IS DISTINCT FROM OLD.to_revision_id\n     OR NEW.impact_json IS DISTINCT FROM OLD.impact_json\n     OR NEW.expected_track_version IS DISTINCT FROM OLD.expected_track_version\n     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key\n     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Tutor track plan migration evidence is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = NEW.status\n     AND (\n       NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at\n       OR NEW.applied_at IS DISTINCT FROM OLD.applied_at\n     ) THEN\n    RAISE EXCEPTION 'Tutor track plan migration timestamps are immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'proposed' THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'confirmed'\n     AND OLD.confirmed_at IS NULL AND NEW.confirmed_at IS NOT NULL AND NEW.applied_at IS NULL THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'applied'\n     AND OLD.confirmed_at IS NULL AND NEW.confirmed_at IS NOT NULL AND NEW.applied_at IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'rejected'\n     AND NEW.confirmed_at IS NULL AND NEW.applied_at IS NULL THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = 'confirmed' AND NEW.status = 'confirmed' THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = 'confirmed' AND NEW.status = 'applied'\n     AND NEW.confirmed_at IS NOT DISTINCT FROM OLD.confirmed_at AND NEW.applied_at IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status = NEW.status AND OLD.status IN ('applied', 'rejected') THEN\n    RETURN NEW;\n  END IF;\n  RAISE EXCEPTION 'Tutor track plan migration lifecycle transition is invalid' USING ERRCODE = '23514';\nEND;\n"), ('public.enforce_tutor_track_plan_revision_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.status = 'active' AND NEW.predecessor_revision_id IS NULL AND NEW.activated_at IS NOT NULL THEN\n      RETURN NEW;\n    END IF;\n    IF NEW.status = 'proposed' AND NEW.predecessor_revision_id IS NOT NULL AND NEW.activated_at IS NULL THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION 'Tutor track plan revision initial lifecycle is invalid' USING ERRCODE = '23514';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    IF NOT tutor_learning_track_purge_allowed(OLD.user_id) THEN\n      RAISE EXCEPTION 'Tutor track plan revisions are immutable' USING ERRCODE = '23514';\n    END IF;\n    RETURN OLD;\n  END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id\n     OR NEW.track_id IS DISTINCT FROM OLD.track_id\n     OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.predecessor_revision_id IS DISTINCT FROM OLD.predecessor_revision_id\n     OR NEW.title IS DISTINCT FROM OLD.title\n     OR NEW.target_level IS DISTINCT FROM OLD.target_level\n     OR NEW.plan_json IS DISTINCT FROM OLD.plan_json\n     OR NEW.generator_version IS DISTINCT FROM OLD.generator_version\n     OR NEW.policy_version IS DISTINCT FROM OLD.policy_version\n     OR NEW.change_reason IS DISTINCT FROM OLD.change_reason\n     OR NEW.content_hash IS DISTINCT FROM OLD.content_hash\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Tutor track plan revision content is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status IN ('proposed', 'active', 'rejected') THEN\n    NULL;\n  ELSIF OLD.status = 'active' AND NEW.status IN ('active', 'superseded') THEN\n    NULL;\n  ELSIF OLD.status = NEW.status AND OLD.status IN ('superseded', 'rejected') THEN\n    NULL;\n  ELSE\n    RAISE EXCEPTION 'Tutor track plan revision lifecycle transition is invalid' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = NEW.status AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN\n    RAISE EXCEPTION 'Tutor track plan revision activation timestamp is immutable' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'active'\n     AND (OLD.activated_at IS NOT NULL OR NEW.activated_at IS NULL) THEN\n    RAISE EXCEPTION 'Tutor track plan revision activation timestamp is invalid' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'proposed' AND NEW.status = 'rejected'\n     AND NEW.activated_at IS NOT NULL THEN\n    RAISE EXCEPTION 'Rejected Tutor track plan revision cannot be activated' USING ERRCODE = '23514';\n  END IF;\n  IF OLD.status = 'active' AND NEW.status = 'superseded'\n     AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN\n    RAISE EXCEPTION 'Superseded Tutor track plan revision must preserve activation time' USING ERRCODE = '23514';\n  END IF;\n  RETURN NEW;\nEND;\n"), ('public.enforce_tutor_track_plan_structure_immutable()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP = 'DELETE' AND tutor_learning_track_purge_allowed(OLD.user_id) THEN\n    RETURN OLD;\n  END IF;\n  RAISE EXCEPTION 'Tutor track plan structure is immutable' USING ERRCODE = '23514';\nEND;\n"), ('public.rag_discovery_actor_owner_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP='UPDATE' OR EXISTS (\n    SELECT 1 FROM rag_discovery_job_refs WHERE actor_id=OLD.actor_id\n  ) OR EXISTS (\n    SELECT 1 FROM rag_candidate_private_refs WHERE actor_id=OLD.actor_id\n  ) THEN\n    RAISE EXCEPTION 'actor owner change denied while referenced' USING ERRCODE='23514';\n  END IF;\n  RETURN OLD;\nEND "), ('public.rag_discovery_context_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nBEGIN\n  IF TG_OP <> 'INSERT' THEN\n    RAISE EXCEPTION 'discovery context is immutable' USING ERRCODE='23514';\n  END IF;\n  IF TG_TABLE_NAME = 'rag_discovery_private_contexts' AND NOT EXISTS (\n    SELECT 1 FROM rag_discovery_actor_owners o\n    WHERE o.actor_id=NEW.actor_id AND o.user_id=NEW.user_id\n  ) THEN\n    RAISE EXCEPTION 'actor owner mismatch' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND "), ('public.rag_registered_capture_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE fetch_row rag_registered_fetch_attempts%ROWTYPE;\nDECLARE grant_row rag_registered_source_policies%ROWTYPE;\nBEGIN\n  IF TG_OP='INSERT' THEN\n    SELECT * INTO fetch_row FROM rag_registered_fetch_attempts WHERE id=NEW.fetch_attempt_id;\n    SELECT * INTO grant_row FROM rag_registered_source_policies\n      WHERE policy_id=NEW.policy_id AND generation=NEW.generation;\n    IF NEW.cleared_at IS NOT NULL OR NEW.retention_until<=clock_timestamp() OR\n       fetch_row.id IS NULL OR grant_row.policy_id IS NULL OR\n       fetch_row.state<>'settled' OR fetch_row.policy_id<>NEW.policy_id OR\n       fetch_row.generation<>NEW.generation OR\n       fetch_row.response_sha256<>NEW.fetched_sha256 OR\n       fetch_row.response_bytes<>NEW.captured_bytes OR\n       grant_row.enabled IS NOT TRUE OR grant_row.revoked_at IS NOT NULL OR\n       grant_row.expires_at<=clock_timestamp() OR\n       grant_row.license_id<>NEW.license_id OR\n       NEW.retention_until>grant_row.retention_until OR\n       NEW.captured_bytes>grant_row.max_captured_bytes OR\n       NEW.final_url<>grant_row.canonical_url OR\n       NEW.request_chain->>0<>grant_row.canonical_url OR\n       encode(digest(NEW.captured_body,'sha256'),'hex')<>NEW.fetched_sha256 THEN\n      RAISE EXCEPTION 'registered capture not authorized or inconsistent' USING ERRCODE='23514';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF TG_OP='DELETE' OR OLD.cleared_at IS NOT NULL OR NEW.cleared_at IS NULL OR\n     NEW.captured_body IS NOT NULL OR\n     (to_jsonb(NEW)-'captured_body'-'cleared_at') IS DISTINCT FROM\n     (to_jsonb(OLD)-'captured_body'-'cleared_at') THEN\n    RAISE EXCEPTION 'registered capture immutable or cleared' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND "), ('public.rag_source_admission_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE reviewed rag_source_reviews%ROWTYPE;\nBEGIN\n  IF TG_OP='DELETE' THEN\n    RAISE EXCEPTION 'source admission deletion denied' USING ERRCODE='23514';\n  END IF;\n  IF TG_OP='UPDATE' THEN\n    IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.active OR\n       (to_jsonb(NEW)-'active'-'revoked_at') IS DISTINCT FROM\n       (to_jsonb(OLD)-'active'-'revoked_at') THEN\n      RAISE EXCEPTION 'source admission immutable or revoked' USING ERRCODE='23514';\n    END IF;\n    RETURN NEW;\n  END IF;\n  SELECT * INTO reviewed FROM rag_source_reviews WHERE id=NEW.review_id;\n  IF NOT FOUND OR reviewed.status<>'reviewed' OR\n     NOT NEW.allowed_usages <@ reviewed.allowed_usages OR\n     NEW.policy_generation<>reviewed.policy_generation THEN\n    RAISE EXCEPTION 'source review not admitted' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND "), ('public.rag_source_claim_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE primary_review rag_source_reviews%ROWTYPE;\nDECLARE secondary_review rag_source_reviews%ROWTYPE;\nBEGIN\n  IF TG_OP<>'INSERT' THEN\n    RAISE EXCEPTION 'claim receipt immutable' USING ERRCODE='23514';\n  END IF;\n  -- No execution verifier adapter is installed in C's default-off runtime.\n  -- A text handle alone is not proof that a process was actually isolated/run.\n  IF TG_TABLE_NAME='rag_source_claim_receipts' THEN\n    IF NEW.method='isolated_execution' THEN\n      RAISE EXCEPTION 'isolated execution verifier unavailable' USING ERRCODE='23514';\n    END IF;\n    SELECT review.* INTO primary_review FROM rag_source_reviews review\n      JOIN rag_source_admissions admission ON admission.review_id=review.id\n      WHERE admission.id=NEW.admission_id AND admission.active FOR SHARE OF review,admission;\n    SELECT review.* INTO secondary_review FROM rag_source_reviews review\n      JOIN rag_source_admissions admission ON admission.review_id=review.id\n      WHERE admission.id=NEW.independent_admission_id AND admission.active FOR SHARE OF review,admission;\n    IF primary_review.id IS NULL OR secondary_review.id IS NULL OR\n       primary_review.document_hash<>NEW.source_document_hash OR\n       secondary_review.document_hash<>NEW.independent_document_hash OR\n       primary_review.lineage_family=secondary_review.lineage_family OR\n       primary_review.subject_id<>NEW.subject_id OR\n       secondary_review.subject_id<>NEW.subject_id OR\n       primary_review.subject_version<>NEW.subject_version OR\n       secondary_review.subject_version<>NEW.subject_version THEN\n      RAISE EXCEPTION 'claim lineage or scope unverified' USING ERRCODE='23514';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND "), ('public.rag_source_review_guard()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', "\nDECLARE original_hash text;\nDECLARE policy_row rag_registered_source_policies%ROWTYPE;\nBEGIN\n  IF TG_OP<>'INSERT' THEN\n    RAISE EXCEPTION 'source review immutable' USING ERRCODE='23514';\n  END IF;\n  IF NEW.registered_capture_id IS NOT NULL THEN\n    SELECT capture.fetched_sha256 INTO original_hash\n      FROM rag_registered_source_captures capture\n      WHERE capture.id=NEW.registered_capture_id AND capture.cleared_at IS NULL\n        AND capture.captured_body IS NOT NULL;\n    SELECT policy.* INTO policy_row FROM rag_registered_source_policies policy\n      JOIN rag_registered_source_captures capture ON capture.policy_id=policy.policy_id\n        AND capture.generation=policy.generation\n      WHERE capture.id=NEW.registered_capture_id;\n    IF policy_row.policy_id IS NULL OR NEW.source_handle<>policy_row.source_handle OR\n       NEW.subject_id<>policy_row.subject_id OR\n       NEW.subject_version<>policy_row.subject_version OR\n       NOT NEW.facets <@ policy_row.facets OR\n       NEW.origin<>policy_row.origin OR NEW.reading_level<>policy_row.reading_level OR\n       NEW.license_id<>policy_row.license_id OR\n       NEW.policy_id<>policy_row.policy_id OR\n       NEW.policy_generation<>policy_row.generation OR\n       NEW.root_id<>policy_row.root_id OR\n       NOT NEW.allowed_usages <@ policy_row.allowed_usages OR\n       (NEW.immutable_history_allowed AND NOT policy_row.immutable_history_allowed) OR\n       (NEW.status='reviewed' AND (policy_row.enabled IS NOT TRUE OR\n            policy_row.revoked_at IS NOT NULL OR policy_row.expires_at<=clock_timestamp())) THEN\n      RAISE EXCEPTION 'review source scope or permission mismatch' USING ERRCODE='23514';\n    END IF;\n  ELSE\n    SELECT full_sha256 INTO original_hash FROM rag_candidate_captures\n      WHERE id=NEW.candidate_capture_id AND capture_kind='full' AND cleared_at IS NULL;\n  END IF;\n  IF original_hash IS NULL OR original_hash<>NEW.document_hash THEN\n    RAISE EXCEPTION 'review document hash mismatch' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND "), ('public.set_updated_at()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', '\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n'), ('public.tutor_action_purge_allowed(text)', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'boolean', False, 'u', '\nDECLARE\n  target_user_id uuid;\nBEGIN\n  SELECT user_id INTO target_user_id\n  FROM tutor_action_invocations\n  WHERE id = target_invocation_id;\n  RETURN target_user_id IS NOT NULL AND tutor_learning_track_purge_allowed(target_user_id);\nEND;\n'), ('public.tutor_artifact_supersession_successor(uuid)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'sql', 'uuid', True, 'u', "\n  WITH RECURSIVE descendants AS (\n    SELECT child.*, 1 AS depth, ARRAY[a.teaching_session_id,child.id] AS lineage\n    FROM tutor_learning_artifacts a\n    JOIN tutor_teaching_sessions parent ON parent.id=a.teaching_session_id\n      AND parent.user_id=a.user_id AND parent.conversation_id=a.conversation_id\n      AND parent.track_id=a.learning_track_id AND parent.knowledge_key=a.knowledge_key\n      AND parent.status='blocked'\n    JOIN tutor_teaching_sessions child ON child.predecessor_session_id=parent.id\n      AND child.user_id=parent.user_id AND child.conversation_id=parent.conversation_id\n      AND child.track_id=parent.track_id AND child.knowledge_key=parent.knowledge_key\n    WHERE a.id=p_artifact_id\n    UNION ALL\n    SELECT child.*, d.depth+1, d.lineage || child.id\n    FROM descendants d\n    JOIN tutor_teaching_sessions child ON child.predecessor_session_id=d.id\n      AND child.user_id=d.user_id AND child.conversation_id=d.conversation_id\n      AND child.track_id=d.track_id AND child.knowledge_key=d.knowledge_key\n    WHERE d.status='blocked' AND d.depth<32 AND NOT child.id=ANY(d.lineage)\n  )\n  SELECT d.id FROM descendants d\n  JOIN tutor_learning_tracks t ON t.id=d.track_id AND t.user_id=d.user_id\n    AND t.version=d.track_version\n  JOIN tutor_track_active_plans p ON p.track_id=d.track_id AND p.user_id=d.user_id\n    AND p.revision_id=d.active_plan_revision_id\n  JOIN tutor_track_node_progress progress ON progress.track_id=d.track_id\n    AND progress.user_id=d.user_id AND progress.knowledge_key=d.knowledge_key\n    AND progress.version=d.progress_version\n  JOIN tutor_lesson_assignments assignment ON assignment.id=d.lesson_assignment_id\n    AND assignment.user_id=d.user_id AND assignment.track_id=d.track_id\n    AND assignment.knowledge_key=d.knowledge_key AND assignment.status='active'\n    AND assignment.assignment_version=d.assignment_version AND assignment.document_id=d.document_id\n  WHERE d.status IN ('active','paused','completed')\n  ORDER BY d.depth DESC,d.created_at DESC,d.id DESC LIMIT 1;\n"), ('public.tutor_branch_authority_replacement_valid(uuid,uuid,uuid,text,uuid,uuid)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'sql', 'boolean', False, 'u', "\n  SELECT EXISTS (\n    SELECT 1 FROM tutor_teaching_sessions AS old\n    JOIN tutor_teaching_sessions AS successor ON successor.predecessor_session_id = old.id\n    WHERE old.id = old_session AND successor.id = new_session AND old.status = 'blocked'\n      AND (old.user_id, old.conversation_id, old.track_id, old.knowledge_key)\n        = (branch_user, branch_conversation, branch_track, branch_knowledge)\n      AND (successor.user_id, successor.conversation_id, successor.track_id, successor.knowledge_key)\n        = (old.user_id, old.conversation_id, old.track_id, old.knowledge_key)\n      AND ROW(old.track_version, old.active_plan_revision_id, old.progress_version,\n              old.lesson_assignment_id, old.assignment_version, old.document_id, old.document_content_hash)\n        IS DISTINCT FROM\n          ROW(successor.track_version, successor.active_plan_revision_id, successor.progress_version,\n              successor.lesson_assignment_id, successor.assignment_version, successor.document_id, successor.document_content_hash)\n      AND NOT EXISTS (\n        SELECT 1 FROM tutor_runs AS runs\n        JOIN tutor_run_teaching_scopes AS scopes ON scopes.run_id = runs.id\n        WHERE scopes.teaching_session_id = old.id AND runs.user_id = old.user_id\n          AND runs.terminal_outcome IS NULL AND runs.cancelled_at IS NULL\n          AND runs.superseded_by_run_id IS NULL\n      )\n  );\n"), ('public.tutor_demo_completion_continuation_valid(uuid,uuid,uuid,text,text,integer,integer)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'sql', 'boolean', False, 'u', "\n  SELECT EXISTS (\n    SELECT 1\n    FROM tutor_demonstration_completion_receipts AS receipts\n    JOIN tutor_learning_artifacts AS artifacts\n      ON artifacts.id = receipts.artifact_id\n     AND artifacts.user_id = receipts.user_id\n     AND artifacts.conversation_id = receipts.conversation_id\n    JOIN tutor_learning_artifact_events AS events\n      ON events.artifact_id = artifacts.id\n     AND events.user_id = artifacts.user_id\n     AND events.conversation_id = artifacts.conversation_id\n     AND events.teaching_session_id = artifacts.teaching_session_id\n    WHERE artifacts.id = p_artifact_id\n      AND artifacts.user_id = p_user_id\n      AND artifacts.conversation_id = p_conversation_id\n      AND artifacts.artifact_kind = 'demonstration'\n      AND artifacts.presentation_kind = 'demonstration_v2'\n      AND artifacts.state = 'completed'\n      AND artifacts.version = p_artifact_version\n      AND artifacts.version = events.to_version\n      AND artifacts.presentation_hash = receipts.descriptor_hash\n      AND receipts.completion_kind = CASE p_source_kind\n        WHEN 'expected_interactive_event' THEN 'interactive_event'\n        WHEN 'static_display_timer' THEN 'visible_clock'\n        ELSE NULL\n      END\n      AND events.id::text = p_source_id\n      AND events.event_sequence = p_source_version\n      AND events.event_kind = 'action'\n      AND events.action_kind = 'complete_demo'\n      AND events.safe_payload_json->'owner_result'->>'completion_receipt_id' = receipts.id::text\n      AND events.safe_payload_json->'owner_result'->>'completion_kind' = receipts.completion_kind\n      AND events.safe_payload_json->'owner_result'->>'descriptor_hash' = receipts.descriptor_hash\n  );\n"), ('public.tutor_learning_artifact_attempt_owner_matches(uuid,uuid,uuid,text,uuid,text,uuid,uuid)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'boolean', False, 'u', "\nDECLARE\n  attempt_row tutor_exercise_attempts%ROWTYPE;\n  session_assignment_id uuid;\n  session_plan_revision_id uuid;\n  item_exercise_id uuid;\nBEGIN\n  SELECT * INTO attempt_row\n  FROM tutor_exercise_attempts\n  WHERE id=target_attempt_id\n    AND user_id=target_user_id\n    AND track_id=target_track_id\n    AND knowledge_key=target_knowledge_key;\n  IF attempt_row.id IS NULL THEN RETURN false; END IF;\n\n  SELECT lesson_assignment_id,active_plan_revision_id INTO session_assignment_id,session_plan_revision_id\n  FROM tutor_teaching_sessions\n  WHERE id=target_teaching_session_id\n    AND user_id=target_user_id\n    AND conversation_id=target_conversation_id\n    AND track_id=target_track_id\n    AND knowledge_key=target_knowledge_key;\n  IF session_assignment_id IS NULL THEN RETURN false; END IF;\n\n  IF target_owner_kind='lesson_gate' THEN\n    RETURN attempt_row.learning_item_version_id IS NULL\n      AND attempt_row.attempt_type IN ('run','submit')\n      AND attempt_row.lesson_assignment_id=session_assignment_id\n      AND EXISTS (\n        SELECT 1 FROM tutor_lesson_gate_states AS states\n        WHERE states.id=target_owner_id\n          AND states.user_id=target_user_id\n          AND states.track_id=target_track_id\n          AND states.knowledge_key=target_knowledge_key\n          AND states.lesson_assignment_id=session_assignment_id\n          AND states.gate_binding_id=attempt_row.gate_binding_id\n      );\n  ELSIF target_owner_kind='review_item' THEN\n    RETURN attempt_row.learning_item_version_id IS NULL\n      AND attempt_row.attempt_type='review_submit'\n      AND attempt_row.review_item_id=target_owner_id\n      AND EXISTS (\n        SELECT 1 FROM tutor_review_items AS items\n        WHERE items.id=target_owner_id\n          AND items.user_id=target_user_id\n          AND items.track_id=target_track_id\n          AND items.knowledge_key=target_knowledge_key\n          AND items.session_id=attempt_row.review_session_id\n      );\n  ELSIF target_owner_kind='teaching_practice' THEN\n    RETURN attempt_row.learning_item_version_id IS NULL\n      AND attempt_row.attempt_type IN ('run','submit')\n      AND attempt_row.lesson_assignment_id=session_assignment_id;\n  ELSIF target_owner_kind='learning_item' THEN\n    SELECT materializations.exercise_version_id INTO item_exercise_id\n    FROM tutor_learning_item_versions AS versions\n    JOIN tutor_learning_item_practice_materializations AS materializations\n      ON materializations.version_id=versions.id\n    JOIN LATERAL (\n      SELECT state,state_version\n      FROM tutor_learning_item_publication_events AS publication\n      WHERE publication.version_id=versions.id\n      ORDER BY state_version DESC LIMIT 1\n    ) AS publication ON publication.state='published'\n    WHERE versions.id=target_owner_id\n      AND versions.knowledge_key=tutor_plan_catalog_knowledge_key(\n        target_user_id,target_track_id,session_plan_revision_id,target_knowledge_key\n      );\n    RETURN item_exercise_id IS NOT NULL\n      AND attempt_row.attempt_type='run'\n      AND attempt_row.learning_item_version_id=target_owner_id\n      AND attempt_row.exercise_version_id=item_exercise_id\n      AND attempt_row.lesson_assignment_id=session_assignment_id\n      AND attempt_row.gate_binding_id IS NULL;\n  END IF;\n  RETURN false;\nEND;\n"), ('public.tutor_learning_track_purge_allowed(uuid)', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'boolean', False, 'u', "\nBEGIN\n  RETURN current_setting('aearn.learning_track_purge_user_id', true) = target_user_id::text;\nEND;\n"), ('public.tutor_model_review_purge_allowed(uuid)', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'boolean', False, 'u', '\nBEGIN\n  RETURN tutor_learning_track_purge_allowed(target_user_id);\nEND;\n'), ('public.tutor_teaching_checkpoint_descends_from(uuid,uuid,uuid,uuid,uuid)', 'postgres', False, 's', None, (('PUBLIC', False), ('postgres', False)), 'sql', 'boolean', False, 'u', '\n  WITH RECURSIVE lineage AS (\n    SELECT checkpoints.id, checkpoints.predecessor_checkpoint_id\n    FROM tutor_teaching_session_checkpoints AS checkpoints\n    WHERE checkpoints.id = checkpoint_id_value\n      AND checkpoints.teaching_session_id = teaching_session_id_value\n      AND checkpoints.user_id = user_id_value\n      AND checkpoints.conversation_id = conversation_id_value\n    UNION ALL\n    SELECT predecessor.id, predecessor.predecessor_checkpoint_id\n    FROM tutor_teaching_session_checkpoints AS predecessor\n    JOIN lineage ON lineage.predecessor_checkpoint_id = predecessor.id\n    WHERE predecessor.teaching_session_id = teaching_session_id_value\n      AND predecessor.user_id = user_id_value\n      AND predecessor.conversation_id = conversation_id_value\n  )\n  SELECT EXISTS (\n    SELECT 1 FROM lineage WHERE id = ancestor_checkpoint_id_value\n  );\n'), ('public.enforce_language_course_intent_coverage()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'trigger', False, 'u', '\nBEGIN\n  PERFORM assert_language_course_intent_coverage();\n  RETURN NULL;\nEND;\n'), ('public.assert_language_course_intent_coverage()', 'postgres', False, 'v', None, (('PUBLIC', False), ('postgres', False)), 'plpgsql', 'void', False, 'u', "\nDECLARE\n  missing_courses text;\n  missing_intents text;\nBEGIN\n  SELECT string_agg(courses.slug, ',' ORDER BY courses.slug)\n  INTO missing_courses\n  FROM language_courses AS courses\n  WHERE courses.archived_at IS NULL\n    AND NOT EXISTS (\n      SELECT 1\n      FROM language_course_intent_tags AS tags\n      JOIN tutor_learning_intents AS intents\n        ON intents.intent_key = tags.intent_key AND intents.state = 'active'\n      WHERE tags.course_id = courses.id\n    );\n\n  IF missing_courses IS NOT NULL THEN\n    RAISE EXCEPTION 'language_course_intent_coverage_missing: active courses without tags: %', missing_courses\n      USING ERRCODE = '23514';\n  END IF;\n\n  SELECT string_agg(intents.intent_key, ',' ORDER BY intents.intent_key)\n  INTO missing_intents\n  FROM tutor_learning_intents AS intents\n  WHERE intents.state = 'active'\n    AND NOT EXISTS (\n      SELECT 1\n      FROM language_course_intent_tags AS tags\n      JOIN language_courses AS courses\n        ON courses.id = tags.course_id AND courses.archived_at IS NULL\n      WHERE tags.intent_key = intents.intent_key\n    );\n\n  IF missing_intents IS NOT NULL THEN\n    RAISE EXCEPTION 'language_course_intent_coverage_missing: active intents without courses: %', missing_intents\n      USING ERRCODE = '23514';\n  END IF;\nEND;\n"))

